/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('patriarch','From Greek patriarkhēs, built from patria “family/lineage” + arkhein “to rule”; a patriarch is the oldest or most respected man leading a family or community.',C('patriarch.s1','社会','At the reunion, the family’s patriarch welcomed each branch of the family and told stories about their shared history.','家庭聚会上，家族长者欢迎各房亲属，并讲述他们共同的历史。','At the reunion / the family’s patriarch welcomed each branch / and told stories / about their shared history.','patriarch.s1 指领导家庭或社群的年长或受尊敬男子。','他在家族聚会中承担长者和领头人的角色。','word-formation'),M('The family called a young visitor its patriarch even though he had no leadership role and was not a respected elder.','The family called its respected senior leader its patriarch.','patriarch 指家族或社群的长者领袖，不是随便一位访客。','meaning'),[Q(1,'What role did the family’s patriarch have at the reunion?','He welcomed relatives and shared family history.','He delivered a package for the host.','He managed the hotel’s night shift.','patriarch.s1 is an elder or respected leader of a family/community.'),Q(1,'Who is most likely a patriarch?','A respected senior man who leads a family.','A new visitor with no connection or authority.','A child who is attending a reunion.','The patriarch is an elder leader.'),Q(1,'What is the core idea of patriarch?','A fatherly or senior male head of a family or community.','A paid public guard.','An amount that is too small.','The Greek roots combine family lineage and rule.'),Q(1,'Which Greek element in patriarch means “to rule”?','arkhein','paucus','pater','arkhein means to rule.','word-formation')]);
P('patriarchal','From patriarch + -al; it describes a social or family system in which men hold authority.',C('patriarchal.s1','社会','The historian described the old inheritance law as patriarchal because only male relatives could control family land.','历史学家称旧继承法为父权制的，因为只有男性亲属能支配家族土地。','The historian described the old inheritance law as patriarchal / because only male relatives / could control family land.','patriarchal.s1 指男性在家庭或社会制度中掌握权威的。','土地继承权只授予男性。','word-formation'),M('The historian called the law patriarchal even though it gave women and men equal authority over inheritance.','The historian called the law patriarchal because it reserved inheritance authority for male relatives.','男女平等掌权不体现男性主导的父权制度。','distinction'),[Q(1,'Why did the historian call the law patriarchal?','Only male relatives could control family land.','All relatives had equal authority.','The law concerned only a public parade.','patriarchal.s1 describes male authority in a system.'),Q(1,'Which arrangement is patriarchal?','A family rule giving leadership and property control only to men.','A rule distributing authority equally among all genders.','A workplace with no managers.','The first arrangement privileges men in authority.'),Q(1,'What does patriarchal describe?','A system in which men hold family or social authority.','An individual’s low income.','A repeated decorative shape.','The adjective relates to patriarchal organization.'),Q(1,'What does -al do in patriarchal?','Forms an adjective meaning related to a patriarch.','Forms a plural noun.','Means “without fathers.”','The suffix -al derives an adjective from patriarch.','word-formation')]);
P('patriarchic','From patriarch + -ic; it means relating to a social order led by male family heads.',C('patriarchic.s1','社会','The anthropologist noted that the council’s patriarchic structure gave senior men control over household decisions.','人类学家指出，该委员会的父权结构让年长男性控制家庭决策。','The anthropologist noted / that the council’s patriarchic structure / gave senior men control / over household decisions.','patriarchic.s1 指与男性家长掌权的社会制度有关。','权力集中在年长男性手中。','word-formation'),M('The article called the council patriarchic while explaining that leadership passed equally among men and women.','The article called the council patriarchic because senior men held the leadership roles.','男女平等掌握领导权不符合 patriarchic 的定义。','distinction'),[Q(1,'What made the council patriarchic?','Senior men controlled household decisions.','Leadership was shared equally among everyone.','The council had no social rules.','patriarchic.s1 relates to male-headed social organization.'),Q(1,'Which phrase fits patriarchic?','a patriarchic household structure','a patriarchic amount of rain','a patriarchic packet of data','The adjective describes a social structure led by male heads.'),Q(1,'What does patriarchic relate to?','A social system ruled by men as family heads.','A person who patrols a building.','A small flat food cake.','The source sense concerns male family authority.'),Q(1,'Which suffix appears in patriarchic?','-ic','-ful','-ment','The adjective is formed with -ic.','word-formation')]);
P('patriarchy','From Greek patriarkhia, from patriarkhēs “head of a family”; it names social organization that privileges fathers or men as rulers.',C('patriarchy.s1','社会','The essay examined how the patriarchy shaped property laws that gave fathers control of family assets.','文章分析了父权制如何塑造财产法，使父亲控制家庭资产。','The essay examined / how the patriarchy shaped property laws / that gave fathers control / of family assets.','patriarchy.s1 指以父亲或男性为统治者并赋予其特权的社会组织。','法律把资产控制权交给父亲。'),M('The essay described a system with equal power-sharing as patriarchy even though fathers and men held no special authority.','The essay described a system that granted men special authority as a patriarchy.','没有男性特权或父亲统治的平等制度不符合父权制含义。','meaning'),[Q(1,'What did the patriarchy shape in the essay?','Property laws giving fathers control of family assets.','The color pattern on a wall.','The number of pages in a report.','patriarchy.s1 describes a social system privileging fathers or men.'),Q(1,'Which situation reflects patriarchy?','A society where men hold institutional power over women.','A society where authority is equally shared.','A family with no shared decisions.','The first situation gives men systemic authority.'),Q(1,'What does patriarchy name?','A social organization privileging fathers or men as rulers.','A single family reunion.','A small amount of a needed resource.','The noun names the broader social system.'),Q(1,'Which word is the direct source for patriarchy?','patriarch','patrol','paucity','Patriarchy is built from patriarch with -y/-archy formation.','word-formation')]);
P('patrician','From Latin patricius “of the fathers,” from patres “fathers”; it can mean a member of an ancient Roman noble family or describe refined manners associated with high birth.',[C('patrician.s1','历史','The museum’s Roman exhibit identified the senator as a patrician from one of the city’s old noble families.','博物馆的罗马展览指出，这位元老来自城里一个古老贵族家族，是一名贵族。','The museum’s Roman exhibit identified the senator / as a patrician / from one of the city’s old noble families.','patrician.s1 指古罗马贵族家族成员，也可指出身高贵者。','元老被归入古罗马贵族阶层。'),C('patrician.s2','社会','Her patrician manners were evident in the calm, formal way she greeted the guests at the ceremony.','她在典礼上以沉着而正式的方式问候宾客，举止显出贵族气质。','Her patrician manners were evident / in the calm, formal way / she greeted the guests / at the ceremony.','patrician.s2 作形容词，指表现出与高贵出身相连的优雅举止。','正式而从容的待客方式体现优雅举止。')],M('The guide described an ordinary Roman laborer with no noble background as a member of the patrician families.','The guide described a member of an old Roman noble family as a patrician.','古罗马平民劳动者不等于贵族家族成员。','meaning'),[Q(1,'Who was identified as a patrician in the Roman exhibit?','A senator from an old noble family.','A laborer with no noble family connection.','A modern shop patron.','patrician.s1 is a member of an ancient Roman noble family.'),Q(2,'What showed her patrician manners?','A calm, formal greeting at the ceremony.','A loud argument with every guest.','A patrol around the building.','patrician.s2 describes refined behavior associated with high birth.'),Q(1,'What did patrician mean in ancient Rome?','A member of a noble family.','A person who killed a father.','A citizen assigned to a patrol.','The first is the historical class sense.'),Q(2,'Which behavior seems patrician in the example?','Graceful, refined manners.','Careless shouting and rude interruptions.','A formal agreement between states.','The adjective concerns refined manners.','meaning')]);
P('patricide','From Latin pater “father” + -cide “killing”; patricide names the crime of killing one’s own father.',C('patricide.s1','法律','The detective treated the case as suspected patricide because the victim was the accused man’s father.','侦探将案件作为疑似弑父案调查，因为死者是被告的父亲。','The detective treated the case / as suspected patricide / because the victim / was the accused man’s father.','patricide.s1 指杀害自己父亲的罪行。','父子关系符合该词的特定亲属关系。','word-formation'),M('The report called the killing of a stranger patricide even though the victim was not the killer’s father.','The report called the killing of a man’s own father patricide.','杀害陌生人不符合 patricide 的特定亲属含义。','distinction'),[Q(1,'Why was the case suspected patricide?','The victim was the accused man’s father.','The victim was an unrelated passerby.','The case involved a missing package.','patricide.s1 specifically involves killing one’s father.'),Q(1,'Which act is patricide?','A person kills their own father.','A person kills a stranger.','A person argues with a neighbor.','The term is restricted to killing one’s father.'),Q(1,'What does the root pater mean?','Father.','Peace.','Step.','Latin pater means father.'),Q(1,'What does -cide indicate in patricide?','Killing.','A group or team.','A peaceful agreement.','The suffix -cide names killing.','word-formation')]);
P('patriot','From French patriote, from Latin patria “native land”; a patriot is someone who strongly loves and supports their country.',C('patriot.s1','政治','The patriot volunteered after the flood, helping neighbors rebuild while urging officials to protect the whole community.','洪灾后，这位爱国者主动帮助邻居重建，同时敦促官员保护整个社区。','The patriot volunteered after the flood / helping neighbors rebuild / while urging officials / to protect the whole community.','patriot.s1 指深爱并支持自己国家的人。','通过服务公众来支持国家与社区。','word-formation'),M('The speaker called herself a patriot because she wanted her country to fail and refused to support its people.','The speaker called herself a patriot because she cared for her country and worked to support its people.','希望国家受损并拒绝支持公众与爱国者的定义矛盾。','meaning'),[Q(1,'How did the patriot help after the flood?','She volunteered to help neighbors rebuild.','She damaged homes and left the area.','She sold the town’s land abroad.','patriot.s1 is someone who loves and supports the country.'),Q(1,'Who is a patriot?','A person who strongly supports their country.','A person who always opposes its people.','A person who patrols a theater.','The first matches the source definition.'),Q(1,'What does the Latin source patria mean?','Native land or homeland.','A small amount.','A patterned cloth.','Patriot ultimately relates to patria, one’s homeland.'),Q(1,'Which action can express patriotism without violence?','Serving the community and helping it recover.','Attacking civilians.','Rejecting every public responsibility.','Public service can show support for one’s country.','context')]);
P('patriotic','From patriot + -ic; it describes conduct showing love or loyalty to one’s country, or events intended to encourage that feeling.',[C('patriotic.s1','通用','The veterans joined a patriotic ceremony that honored people who had served the country.','退伍军人参加了一场爱国仪式，向曾为国家服务的人致敬。','The veterans joined a patriotic ceremony / that honored people / who had served / the country.','patriotic.s1 指表现出对国家的热爱与忠诚。','仪式表达对国家服务者的敬意。'),C('patriotic.s2','教育','The school organized a patriotic lesson about local history to encourage students to learn how the country developed.','学校组织了一堂关于地方历史的爱国教育课，鼓励学生了解国家的发展。','The school organized a patriotic lesson / about local history / to encourage students / to learn how the country developed.','patriotic.s2 指旨在激发爱国精神的仪式或教育活动。','课程设计旨在鼓励学生了解国家。')],M('The program was called patriotic although it was designed to discourage any interest in the country’s history or public life.','The program was called patriotic because it encouraged students to learn about their country’s history.','旨在压制对国家历史的兴趣与弘扬爱国精神相反。','meaning'),[Q(1,'What did the ceremony honor?','People who had served the country.','People who rejected every public service.','A patroller’s daily route.','patriotic.s1 describes a ceremony expressing love or loyalty to the country.'),Q(2,'Why did the school organize the lesson?','To encourage students to learn about national history.','To keep students from learning any history.','To train them to deliver packages.','patriotic.s2 includes activities intended to encourage national attachment.'),Q(1,'Which act is patriotic?','Taking part in a ceremony honoring public service.','Damaging public buildings for amusement.','Refusing to help anyone in a disaster.','The first action shows support for the country.'),Q(2,'What is a patriotic lesson designed to do?','Encourage students’ interest in their country.','Teach them to avoid all history.','Replace a country with a family patriarch.','The source sense is an activity intended to encourage patriotism.','meaning')]);
P('patriotism','From patriot + -ism; it names devotion to one’s country and willingness to defend or support it.',C('patriotism.s1','政治','Her patriotism led her to serve on the town’s emergency team and advocate for fair access to public services.','她的爱国精神促使她加入镇上的应急队，并倡导公平获得公共服务。','Her patriotism led her / to serve on the town’s emergency team / and advocate / for fair access to public services.','patriotism.s1 指对国家的热爱，以及愿意支持或保卫国家的精神。','社区服务和改善公共服务体现责任感。','word-formation'),M('He described indifference to his country and its people as patriotism, though he refused to help in any way.','He described his commitment to serving the country and its people as patriotism.','对国家和人民漠不关心不是爱国精神。','meaning'),[Q(1,'How did her patriotism lead her to act?','She served the emergency team and advocated for fair services.','She avoided helping the town.','She damaged public property.','patriotism.s1 is devotion expressed as support for the country.'),Q(1,'What does patriotism mean?','Devotion to one’s country and willingness to support it.','A fear of all public events.','A small flat cake.','The noun names love and loyalty toward one’s country.'),Q(1,'Which behavior can express patriotism?','Helping the community during an emergency.','Refusing all responsibility for the community.','Claiming to support a country while harming its people.','Public service is a concrete way to support one’s country.'),Q(1,'Which suffix helps form patriotism?','-ism','-er','-less','-ism forms a noun naming a belief or quality.','word-formation')]);
P('patrol','From French patrouille, from patrouiller “to go about on patrol”; it can name the act of checking an area, a group that does so, or the verb for guarding by moving around.',[C('patrol.s1','安全','The night patrol checks each gate at regular intervals and reports any damage to the control room.','夜间巡逻会定时检查每个大门，并向控制室报告任何损坏。','The night patrol checks each gate / at regular intervals / and reports / any damage to the control room.','patrol.s1 作名词，指定时巡查以确认安全的行动。','巡查按固定间隔进行。'),C('patrol.s2','安全','A patrol of two park rangers reached the trailhead before sunrise and carried radios and first-aid kits.','两名公园护林员组成的巡逻队在日出前抵达步道入口，带着无线电和急救包。','A patrol of two park rangers / reached the trailhead / before sunrise / and carried radios and first-aid kits.','patrol.s2 指执行巡逻的士兵、警察或其他人员小队。','句中 patrol 指一组护林员。'),C('patrol.s3','安全','Volunteers patrol the beach at dawn to keep vehicles away from the nesting shorebirds.','志愿者在黎明时巡查海滩，防止车辆靠近筑巢的滨鸟。','Volunteers patrol the beach / at dawn / to keep vehicles away / from the nesting shorebirds.','patrol.s3 作动词，指在某地区往来守卫或巡查。','志愿者在海滩范围内巡视。')],M('The volunteers said they patrolled the beach all morning, but they remained at home and never visited it.','The volunteers patrolled the beach by walking its length and checking access points.','没有到现场就没有在该地点巡逻。','meaning'),[Q(1,'What does the night patrol do regularly?','Checks gates and reports damage.','Delivers a patronage grant.','Repairs every trail before sunrise.','patrol.s1 is the act of regular safety checks.'),Q(2,'Who made up the patrol in the second context?','Two park rangers.','Two visitors with no duty.','A family reunion.','patrol.s2 can mean the group assigned to patrol.'),Q(3,'Why do volunteers patrol the beach?','To keep vehicles away from nesting birds.','To paint the shoreline.','To sell pails of water.','patrol.s3 is the verb for guarding an area by moving around.'),Q(1,'Which phrase uses patrol as an action noun?','The night patrol lasted until sunrise.','The patrol walked the beach.','They patrol the beach.','The first uses patrol for the act or period of checking.','grammar')]);
P('patroller','From patrol + -er; it names a person who moves around an area to guard or inspect it.',C('patroller.s1','安全','The patroller walked the empty station platform, checked the emergency exits, and logged that all doors were secure.','巡逻人员巡视了空车站站台，检查紧急出口，并记录所有大门均已锁好。','The patroller walked the empty station platform / checked the emergency exits / and logged / that all doors were secure.','patroller.s1 指在某地巡查以守卫或检查的人。','此人巡视并检查了场所。','word-formation'),M('The manager called a visitor who never inspected or guarded the station a patroller.','The manager called the worker who inspected the station a patroller.','没有巡查或守卫职责的访客不是 patroller。','meaning'),[Q(1,'What did the patroller check?','The station’s emergency exits and doors.','A recipe for a patty.','A Roman noble family.','patroller.s1 is someone who guards or inspects an area.'),Q(1,'Who is a patroller?','A worker walking around a site to check it.','A visitor who never checks anything.','A patron who eats at a restaurant.','The worker performs the patrol.'),Q(1,'Which task belongs to a patroller?','Inspecting doors on a night round.','Writing an academic page about fossils.','Mixing paint on a palette.','A patroller checks or guards a place.'),Q(1,'How is patroller formed?','patrol + -er','patriarch + -al','pate + -y','The suffix -er names the person doing the patrolling.','word-formation')]);
P('patron','From Latin patronus “protector, defender,” from pater “father”; it can mean a financial supporter, a regular customer, or a saint believed to protect a group or place.',[C('patron.s1','文化','A local patron funded the theater’s youth program so students could attend performances without charge.','一位当地赞助人资助了剧院的青少年项目，让学生可以免费观演。','A local patron funded the theater’s youth program / so students could attend / performances / without charge.','patron.s1 指向艺术家、慈善机构或组织提供资金和支持的人。','赞助人出资支持剧院项目。'),C('patron.s2','商业','The café thanked its regular patrons with a small anniversary event and free samples of its new tea.','咖啡馆举办小型周年活动并免费提供新茶样品，以感谢常客。','The café thanked its regular patrons / with a small anniversary event / and free samples / of its new tea.','patron.s2 指经常光顾某家商店、餐馆或旅馆的顾客。','这些顾客定期到同一家咖啡馆消费。'),C('patron.s3','宗教','Saint Cecilia is regarded as the patron of musicians, who sometimes ask for her protection before a performance.','圣塞西莉亚被视为音乐家的守护圣徒，演出前音乐家有时祈求她的庇护。','Saint Cecilia is regarded / as the patron of musicians / who sometimes ask for her protection / before a performance.','patron.s3 指被认为保护某地、活动或群体的圣徒。','她被视作音乐家的守护圣徒。')],M('The theater called a donor a patron but claimed that the donor provided no money, support, or help of any kind.','The theater called a donor a patron because the donor funded its youth program.','提供资金和支持是此处称其为 patron 的依据。','meaning'),[Q(1,'What did the local patron fund?','The theater’s youth program.','A café’s free tea samples.','A patrol’s route.','patron.s1 is a supporter who gives money.'),Q(2,'Who are the café’s patrons?','Customers who visit it regularly.','A one-time inspector who never buys anything.','The theater’s student actors.','patron.s2 means a regular customer.'),Q(3,'Why is Saint Cecilia called a patron of musicians?','She is believed to protect them.','She buys coffee every morning.','She funds every theater program.','patron.s3 is a protective saint.'),Q(1,'Which person is a patron in the funding sense?','A donor who supports an arts organization.','A visitor who merely walks past the venue.','A saint mentioned in a prayer.','The donor gives money and support.','distinction')]);
P('patronage','From patron + -age; it can mean support from a patron or customers’ use of a business, as well as a condescending manner or the power to appoint supporters.',[C('patronage.s1','文化','The museum survived through the patronage of several local families who funded conservation work.','博物馆依靠几户当地家庭的资助得以维持，他们出资支持文物保护。','The museum survived / through the patronage of several local families / who funded / conservation work.','patronage.s1 指赞助者提供的资金或支持。','家庭资助帮助博物馆开展保护工作。'),C('patronage.s1','商业','The bakery depends on neighborhood patronage, and regular customers keep it open through the winter.','面包店依靠邻里的惠顾，常客让它得以在冬季继续营业。','The bakery depends on neighborhood patronage / and regular customers / keep it open / through the winter.','patronage.s1 也可指顾客对某家店铺的持续光顾。','邻居经常消费支持店铺经营。'),C('patronage.s2','政治','The historian criticized the mayor’s patronage system, in which public jobs went to political supporters.','历史学家批评市长的政治任命制度，公职被分配给政治支持者。','The historian criticized the mayor’s patronage system / in which public jobs / went to political supporters.','patronage.s2 可指把职位授予支持者的权力或做法。','职位分配依据政治支持。'),C('patronage.s2','社交','Her explanation sounded like patronage because she praised the adults for understanding a simple instruction.','她的解释听起来居高临下，因为她竟夸成年人能听懂简单指示。','Her explanation sounded like patronage / because she praised the adults / for understanding / a simple instruction.','patronage.s2 也可指居高临下、屈尊俯就的态度。','把成年人当作低能者夸奖显得轻慢。')],M('The bakery claimed that patronage from local customers meant residents refused to visit or support the shop.','The bakery credited its continued operation to regular patronage from local customers.','patronage 在商业语境中指顾客支持或惠顾，不是拒绝光顾。','meaning'),[Q(1,'What kept the museum running?','Financial support from local families.','A political appointment system.','A condescending explanation.','patronage.s1 means patron support.'),Q(1,'What does neighborhood patronage mean for the bakery?','Regular customers support it by visiting.','The mayor assigns jobs to supporters.','The owner speaks down to customers.','patronage.s1 can mean customers’ custom.'),Q(2,'How did the mayor’s patronage system work?','Public jobs went to political supporters.','The bakery gained more customers.','The museum received restoration donations.','patronage.s2 can be the power to give jobs to supporters.'),Q(2,'Why did her comment sound like patronage?','It implied the adults were inferior while praising them.','It offered direct financial support.','It described regular visits to a shop.','Patronage can mean a condescending attitude.','distinction')]);
P('patronize','From patron + -ize; it means speak to someone as if they were inferior, or regularly use/support a business.',[C('patronize.s1','社交','The supervisor avoided patronizing the trainee and instead explained the safety rule as a requirement for everyone.','主管没有居高临下地对待实习生，而是说明安全规定对所有人都适用。','The supervisor avoided patronizing the trainee / and instead explained / the safety rule / as a requirement for everyone.','patronize.s1 指以显示对方低人一等的方式说话或对待对方。','规则适用于所有人，避免把实习生当成低能者。'),C('patronize.s2','商业','We patronize the corner bookstore because its staff remember our preferences and order books we request.','我们经常光顾街角书店，因为店员记得我们的喜好，还会订购我们想要的书。','We patronize the corner bookstore / because its staff remember our preferences / and order books / we request.','patronize.s2 指经常光顾商店，也可指出资支持某项事业。','定期在书店购物支持其经营。')],M('The manager patronized the trainee by speaking to her as an equal adult and asking for her expert advice.','The manager patronized the trainee by explaining an obvious task in a babyish tone.','平等交流并请教专业意见不是居高临下的对待。','distinction'),[Q(1,'How did the supervisor avoid patronizing the trainee?','She explained the rule as applying to everyone.','She praised the trainee for understanding a simple sentence.','She refused to explain the rule.','patronize.s1 is speaking as if someone were inferior.'),Q(2,'Why do they patronize the bookstore?','They regularly shop there.','They speak down to its staff.','They appoint political supporters.','patronize.s2 means regularly use or support a business.'),Q(1,'Which remark is patronizing?','“That was a surprisingly clever idea for someone like you.”','“Your proposal identifies a real problem; let’s discuss it.”','“Could you explain your reasoning?”','The first implies the listener is inferior.'),Q(2,'Which sentence uses patronize in the customer sense?','Our family patronizes the small bakery each week.','He patronized her by overexplaining the obvious.','The mayor’s patronage gave jobs to allies.','The first means regularly patronize a business.','distinction')]);
P('patronizing','From patronize + -ing; it describes apparent kindness or praise that implies the other person is inferior.',C('patronizing.s1','社交','Her patronizing reply praised the experienced technician for understanding a basic tool, and he asked her to address him professionally.','她居高临下的回答竟称赞这位资深技师懂得使用基本工具，他请她以专业方式和自己交谈。','Her patronizing reply praised the experienced technician / for understanding / a basic tool / and he asked her to address him professionally.','patronizing.s1 指表面和善、实则暗示对方低人一等的。','过度夸奖对方懂基本工具，暗含轻视。','word-formation'),M('The colleague’s patronizing remark treated the expert as an equal and asked for his professional judgment.','The colleague’s patronizing remark praised the expert for grasping an obvious point in a childish tone.','平等请教专业意见不是暗示对方低人一等。','meaning'),[Q(1,'Why did the technician object to the reply?','It praised him for understanding something basic in a demeaning way.','It asked for his expert opinion respectfully.','It corrected a technical mistake neutrally.','patronizing.s1 implies the listener is inferior.'),Q(1,'Which comment sounds patronizing?','“Well done for figuring out that very simple step.”','“Your analysis helped us solve the issue.”','“Could you check whether this tool is calibrated?”','The first gives condescending praise.'),Q(1,'What does patronizing describe?','Kind-sounding behavior that suggests superiority.','A generous donation to a charity.','Regular shopping at a local store.','The adjective names a condescending manner.'),Q(1,'Which base verb forms patronizing?','patronize','patrol','pattern','Patronizing is the -ing form of patronize.','word-formation')]);
P('pattern','From Anglo-Norman patron, from Old French patron “model”; pattern came to mean a repeated design, regular way, guide/template, or the act of forming or copying a design.',[C('pattern.s1','艺术','The tiles repeat a blue leaf pattern around the border of the kitchen floor.','厨房地板边缘的瓷砖重复着蓝色叶片图案。','The tiles repeat a blue leaf pattern / around the border / of the kitchen floor.','pattern.s1 指重复出现的装饰图案。','叶片图形沿边缘反复出现。'),C('pattern.s2','通用','The analyst noticed a pattern in the complaints: calls increased whenever the delivery window changed.','分析员发现投诉存在规律：每当配送时段改变，来电就会增加。','The analyst noticed a pattern in the complaints / calls increased / whenever the delivery window changed.','pattern.s2 指事情发生或进行的规律方式。','同一条件反复引发投诉。'),C('pattern.s3','通用','She used a paper pattern to cut two identical sleeves for the coat.','她用纸样裁出了这件外套的两只相同袖子。','She used a paper pattern / to cut two identical sleeves / for the coat.','pattern.s3 指制作物品时用作指导的样板或纸样。','纸样用来指导裁剪。'),C('pattern.s4','书面','The new safety procedure was patterned on the system used successfully at the larger hospital.','新的安全流程仿照了那家大型医院已成功使用的制度。','The new safety procedure / was patterned on the system / used successfully / at the larger hospital.','pattern.s4 作动词，指形成规律图案或仿效某个模式。','流程以另一套成功制度为范本。')],M('The analyst called one random complaint a pattern even though no repetition or regular relationship appeared in the records.','The analyst called the repeated rise in calls after each schedule change a pattern.','没有重复或规律关系时，单个偶发事件不足以构成 pattern。','meaning'),[Q(1,'What did the blue leaves form on the tiles?','A repeated decorative design.','A paper template for sleeves.','A regular rise in phone calls.','pattern.s1 is a repeated decorative design.'),Q(2,'What pattern did the analyst find?','Calls increased whenever the delivery window changed.','Calls appeared only once at random.','The tiles had blue leaves.','pattern.s2 is a regular way events occur.'),Q(3,'What did the paper pattern help her do?','Cut two matching sleeves.','Schedule delivery calls.','Decorate the tiles with blue paint.','pattern.s3 is a guide/template for making something.'),Q(4,'What was the new safety procedure patterned on?','A system used successfully at another hospital.','A decorative border of leaves.','A random complaint with no repetition.','pattern.s4 means modeled or based on another example.','distinction')]);
P('patty','A diminutive form related to pate, from French pâté “pie”; a patty is a small flat cake of minced meat or another food.',C('patty.s1','饮食','The cook shaped the black-bean mixture into a patty and grilled it until both sides were crisp.','厨师把黑豆混合物压成小圆饼，烤到两面酥脆。','The cook shaped the black-bean mixture / into a patty / and grilled it / until both sides were crisp.','patty.s1 指用碎肉或其他食材压成的小扁饼。','黑豆混合物被压成扁圆形再烹调。','word-formation'),M('The cook served a bowl of whole beans and called the loose, unshaped beans a flat patty.','The cook pressed the beans into a flat patty before grilling them.','没有压成小扁饼的散豆不是 patty。','meaning'),[Q(1,'What shape did the cook give the black-bean mixture?','A small flat cake.','A tall liquid-filled pail.','A decorative tile pattern.','patty.s1 is a small flat cake made from food.'),Q(1,'Which dish is a patty?','A pressed flat cake of minced meat or beans.','A bowl of loose whole beans.','A whole peach with its stone.','The first has the defining flat, formed shape.'),Q(1,'Can a patty be made from food other than meat?','Yes, such as a pressed bean mixture.','No, it must always be a whole steak.','Only from fruit juice.','The source definition includes other foods.'),Q(1,'What did the cook do before grilling the patty?','Pressed the mixture into a flat shape.','Left it loose in a bowl.','Wrapped it as a postal package.','A patty is formed into a small flat cake.','meaning')]);
P('paucity','From Latin paucitas, from paucus “few”; it means a scarcity or an amount too small for what is needed.',C('paucity.s1','通用','The paucity of clean water forced the village to ration supplies until the repaired well reopened.','清洁水资源匮乏，村民只得限量配给，直到修好的水井重新开放。','The paucity of clean water / forced the village / to ration supplies / until the repaired well reopened.','paucity.s1 指某种资源稀少、数量不足以满足需要。','水量不足导致必须限量使用。','word-formation'),M('The report described a paucity of water even though the reservoir was full and supplies greatly exceeded demand.','The report described a paucity of water after the reservoir dried up and supplies fell below demand.','储量充足且超过需求不构成资源匮乏。','meaning'),[Q(1,'Why did the village ration water?','There was too little clean water available.','The reservoir was overflowing.','The repaired well produced unlimited water.','paucity.s1 means scarcity or an insufficient amount.'),Q(1,'Which situation shows a paucity of evidence?','Only one unclear witness statement supports the claim.','Hundreds of clear records support the claim.','The evidence is complete and consistent.','A very small amount of evidence is a paucity.'),Q(1,'What does paucity mean?','A scarcity or shortage.','A surplus far beyond need.','A regular decorative pattern.','The noun refers to too little of something.'),Q(1,'Which source root means “few”?','paucus','pater','pax','Latin paucus means few.','word-formation')]);
P('pauper','From Latin pauper “poor”; it names someone with almost no money and, historically, someone dependent on public relief.',C('pauper.s1','社会','The archive listed him as a pauper because he had no income and depended on the town’s relief program.','档案把他登记为贫困者，因为他没有收入，依靠镇上的救济项目生活。','The archive listed him as a pauper / because he had no income / and depended on / the town’s relief program.','pauper.s1 指几乎没有钱的人，历史上常指依赖公共救济者。','档案记录了无收入和依赖救济的情况。'),M('The clerk recorded the wealthy landowner with several estates as a pauper who had no money or support.','The clerk recorded the person with no income who relied on public relief as a pauper.','拥有多处产业的富人不符合几乎没有钱的定义。','meaning'),[Q(1,'Why did the archive list him as a pauper?','He had no income and relied on public relief.','He owned several estates.','He funded the town’s theater.','pauper.s1 describes someone with almost no money.'),Q(1,'Who would historically be called a pauper?','Someone dependent on public relief because of extreme poverty.','A wealthy landowner with several estates.','A frequent café customer.','The first fits the historical relief-dependent sense.'),Q(1,'What does pauper mean?','A very poor person.','A patron who funds a museum.','A person who patrols a park.','The word names someone with almost no money.'),Q(1,'Which word is closest in meaning to pauper?','destitute person','wealthy patron','regular customer','Pauper refers to a person in severe poverty.','meaning')]);
P('pause','From Latin pausa, from Greek pausis “a stopping”; as a noun it means a short stop in activity or sound, and as a verb it means stop briefly before continuing.',[C('pause.s1','通用','There was a short pause in the recording when the speaker changed microphones.','演讲者更换麦克风时，录音中出现了一小段停顿。','There was a short pause in the recording / when the speaker / changed microphones.','pause.s1 作名词，指活动或声音短暂停止的一段时间。','录音中的声音短暂中断。'),C('pause.s2','通用','Mina paused before answering the difficult question, then explained how she had reached her conclusion.','米娜回答难题前停顿了一下，然后解释自己是如何得出结论的。','Mina paused / before answering the difficult question / then explained / how she had reached her conclusion.','pause.s2 作动词，指短暂停下后继续。','她停一下再回答。')],M('The recording had no gap at all, but the editor labeled an uninterrupted passage a long pause.','The editor marked the brief silence between the speaker’s sentences as a pause.','没有任何中断的连续声音不是停顿。','meaning'),[Q(1,'What caused the pause in the recording?','The speaker changed microphones.','The speaker continued without any break.','A crowd began a patrol.','pause.s1 is a short period when sound stops.'),Q(2,'What did Mina do before answering?','She stopped briefly and then continued.','She left and never returned.','She read the answer aloud immediately.','pause.s2 means stop briefly before continuing.'),Q(1,'Which phrase uses pause as a noun?','There was a pause before the announcement.','She paused before speaking.','They pause during the song.','The first names the brief stop as a thing.'),Q(2,'Which phrase uses pause as a verb?','The speaker paused to collect his thoughts.','A pause interrupted the recording.','The pause lasted two seconds.','The first describes the action of stopping briefly.','grammar')]);
P('pave','From Old French paver, from Latin pavire “to beat or ram”; it means cover a road or area with stones or asphalt, or figuratively make something easier to happen.',[C('pave.s1','建筑','The city will pave the alley with smooth bricks so delivery carts can pass without shaking.','市政府将用平整的砖铺设小巷，让送货车经过时不再颠簸。','The city will pave the alley / with smooth bricks / so delivery carts can pass / without shaking.','pave.s1 指用石块、砖或沥青铺盖道路或地面。','砖块覆盖了原先凹凸不平的地面。'),C('pave.s2','比喻','The first small trial paved the way for a larger study by showing that the new method was safe.','第一次小规模试验证明新方法安全，为更大规模的研究铺平了道路。','The first small trial / paved the way for a larger study / by showing / that the new method was safe.','pave.s2 常见于 pave the way，表示使某事更容易发生。','安全试验降低了后续研究的障碍。')],M('The city paved the alley by leaving the dirt exposed and adding no stone, brick, or asphalt.','The city paved the alley with bricks over the exposed dirt.','地面仍裸露、未覆盖铺装材料，不能说已铺路。','meaning'),[Q(1,'What will the city use to pave the alley?','Smooth bricks.','Bare soil only.','A velvet curtain.','pave.s1 means cover a surface with paving material.'),Q(2,'How did the trial pave the way for more research?','It showed the method was safe.','It blocked all later studies.','It paved an actual road with asphalt.','pave.s2 means make a future action easier.'),Q(1,'Which task involves paving?','Covering a path with flat stone slabs.','Painting a picture of a path.','Measuring a path without changing it.','Paving covers the surface with hard material.'),Q(2,'What does “pave the way” mean?','Make a later step easier or possible.','Block a path with a fence.','Walk slowly back and forth.','The idiom is figurative rather than literal.','distinction')]);
P('pavement','From Old French pavement, from Latin pavimentum, from pavire “to beat, ram”; in British English it means a raised walkway beside a road, and it can also mean a hard paved surface.',[C('pavement.s1','通用','In Britain, the children walked along the pavement while the cars stayed on the road.','在英国，孩子们沿人行道行走，汽车则在马路上行驶。','In Britain / the children walked along the pavement / while the cars / stayed on the road.','pavement.s1 英式英语指道路旁供行人走的人行道。','行人与汽车分别使用人行道和车道。'),C('pavement.s2','通用','The old pavement cracked under the delivery truck, exposing the concrete base beneath it.','旧路面在送货卡车重压下开裂，露出了下面的混凝土基底。','The old pavement cracked / under the delivery truck / exposing the concrete base / beneath it.','pavement.s2 指石头或混凝土铺成的坚硬路面。','句中 pavement 是车道的硬质表面。')],M('In Britain, the pedestrians walked in the traffic lane while the cars used the raised pavement.','In Britain, pedestrians used the raised pavement and cars used the road.','英式 pavement 是供行人走的人行道，不是机动车道。','distinction'),[Q(1,'Where did the children walk in Britain?','Along the raised path beside the road.','In the traffic lane.','On the roof of the truck.','pavement.s1 is the British sidewalk.'),Q(2,'What cracked beneath the truck?','The hard paved surface.','The raised walkway beside the school only.','A paper pattern.','pavement.s2 is a road or area’s hard surface.'),Q(1,'Which meaning is British English pavement?','A pedestrian walkway beside a road.','A paycheck.','A covered pavilion.','In British use pavement means sidewalk.'),Q(2,'Which sentence uses pavement for road material?','The stone pavement was repaired after frost damage.','She walked along the pavement beside the traffic.','They paved the way for a new project.','The first describes the hard paved surface.','distinction')]);
P('pavid','From Latin pavidus “fearful,” from pavere “to be afraid”; it is a literary adjective meaning timid or showing fear.',C('pavid.s1','文学','The pavid messenger hesitated at the gate, clutching the letter as the guard stepped toward him.','胆怯的信使在门口犹豫不决，卫兵走近时他紧紧攥着信。','The pavid messenger hesitated / at the gate / clutching the letter / as the guard stepped toward him.','pavid.s1 是文学用语，指显出恐惧、胆小的。','犹豫并紧握信件表现出害怕。'),M('The pavid messenger strode forward confidently, laughed at the danger, and showed no sign of fear.','The pavid messenger trembled and hesitated when the guard approached.','毫无恐惧且自信的行为与 pavid 的含义相反。','distinction'),[Q(1,'How did the pavid messenger react to the guard?','He hesitated and clutched the letter.','He confidently rushed past.','He invited the guard to a feast.','pavid.s1 means timid or showing fear.'),Q(1,'Which character could be described as pavid?','A frightened traveler who avoids entering the dark tunnel.','A fearless rescuer who enters first.','A calm guard who feels no concern.','The first person visibly shows fear.'),Q(1,'What is the register of pavid?','Literary.','A common term for wages.','A technical name for paving stones.','The source marks pavid as a literary adjective.'),Q(1,'What does pavid mean?','Timid or fearful.','Generous and supportive.','Smoothly paved.','The adjective describes fearfulness.','meaning')]);
P('pavilion','From French pavillon, from Latin papilio “butterfly,” used for a tent or light structure; today it is a light building for shelter, shows, or sports.',C('pavilion.s1','文化','Visitors rested in the garden pavilion, a light open-sided building shaded by a broad roof.','游客在花园亭子里休息，这座轻巧的开放式建筑由宽阔屋顶遮阳。','Visitors rested / in the garden pavilion / a light open-sided building / shaded by a broad roof.','pavilion.s1 指供遮蔽、展览或体育活动使用的轻便建筑。','开放式建筑用于休憩和遮阳。','word-formation'),M('The museum called an underground sealed storage vault with no shelter or public use a garden pavilion.','The museum called the light garden shelter a pavilion.','地下密封库不是供遮蔽、展览或体育使用的轻便建筑。','meaning'),[Q(1,'Where did visitors rest?','In a light, roofed garden structure.','Inside an underground sealed vault.','On the road pavement.','pavilion.s1 is a light building for shelter or public activities.'),Q(1,'Which structure is a pavilion?','An open-sided shelter in a park.','A private locked filing cabinet.','A narrow strip of asphalt.','A pavilion is a light public-use building.'),Q(1,'What can a pavilion be used for?','Shelter, shows, or sports.','Collecting wages only.','Hiding underground water pipes.','The source sense includes shelter, exhibitions, and sports.'),Q(1,'Which earlier image is associated with the Latin source of pavilion?','A butterfly.','A pea pod.','A father.','The word’s history traces through Latin papilio, “butterfly.”','word-formation')]);
P('paw','Of uncertain origin, recorded in Middle English as pawe; it names an animal’s foot with claws, or the verb for touching/scratching with a paw or handling clumsily.',[C('paw.s1','动物','The dog lifted one muddy paw and left prints across the clean kitchen floor.','狗抬起一只沾泥的爪子，在干净的厨房地板上留下脚印。','The dog lifted one muddy paw / and left prints / across the clean kitchen floor.','paw.s1 指猫、狗、熊等有爪动物的脚掌。','泥脚掌留下了爪印。'),C('paw.s2','通用','The puppy pawed at the closed gate until its owner came to let it into the yard.','小狗用爪子扒着关上的门，直到主人来把它放进院子。','The puppy pawed at the closed gate / until its owner came / to let it into the yard.','paw.s2 作动词，指用爪子触碰或抓扒，也可指笨拙地拨弄。','小狗用爪子扒门。')],M('The puppy pawed the gate by carefully opening it with a key held in its mouth.','The puppy pawed at the gate with its front feet.','用钥匙开门不是用爪子触碰或扒抓。','meaning'),[Q(1,'What left muddy prints on the kitchen floor?','The dog’s paw.','The dog’s paycheck.','A paving brick.','paw.s1 is an animal’s foot with claws.'),Q(2,'What did the puppy do at the gate?','It scratched or touched it with its paws.','It unlocked it with a key.','It paved the path.','paw.s2 means touch or scratch with a paw.'),Q(1,'Which body part is a paw?','A dog’s clawed foot.','A bird’s wing.','A fish’s fin.','A paw is the foot of certain animals.'),Q(2,'Which action is pawing?','A cat bats a toy with its front foot.','A person reads a letter aloud.','A courier packs a box.','The cat is touching an object with its paw.','meaning')]);
P('pawky','A Scots adjective of uncertain origin; it means sly and dryly humorous.',C('pawky.s1','语言','The pawky old storyteller smiled at the audience after making a dry joke about his own forgetfulness.','这位狡黠诙谐的老说书人讲完一个自嘲健忘的冷笑话后，朝观众微笑。','The pawky old storyteller smiled / at the audience / after making a dry joke / about his own forgetfulness.','pawky.s1 指带有狡黠、冷面幽默感的。','说书人的自嘲冷笑话体现诙谐。','register'),M('The comedian’s solemn speech contained no joke, irony, or sly humor, yet the reviewer called it pawky.','The comedian’s sly, dryly humorous remarks were described as pawky.','没有幽默或狡黠意味的严肃讲话不符合 pawky。','meaning'),[Q(1,'What made the storyteller pawky?','He made a dry joke about his own forgetfulness.','He delivered a solemn speech with no humor.','He pawed at a gate.','pawky.s1 means sly and dryly humorous.'),Q(1,'Which remark sounds pawky?','“I’m so organized I misplaced my calendar,” she said with a dry smile.','“The meeting begins at noon,” he said neutrally.','“I refuse to make jokes,” she announced.','The first is a sly, dry joke.'),Q(1,'What is pawky’s usual flavor?','A sly, dry sense of humor.','A formal legal payment.','A loud public pageant.','The adjective describes wry humor.'),Q(1,'What does pawky mean in the passage?','Sly and humorously dry.','Fearful and timid.','Smoothly paved.','The word describes a sly, dry humor.','meaning')]);
P('pawnee','From pawn + -ee, the person to whom a pledge is given; in pawn law a pawnee receives pledged property and may lend money against it.',C('pawnee.s1','法律','The pawnee kept the silver watch as security until the borrower repaid the loan under the written agreement.','在借款人按书面协议偿还贷款前，承典人将银表作为担保保管。','The pawnee kept the silver watch / as security / until the borrower repaid the loan / under the written agreement.','pawnee.s1 指典当法中接受质押物并据此放款的一方。','承典人持有质押表作为借款担保。'),M('The pawnee borrowed money and handed over a watch as collateral, although that role belongs to the pawnor.','The pawnee lent money and received the watch as collateral.','提供质押物并借款的是 pawnor；pawnee 是接受质押的一方。','confusable'),[Q(1,'What did the pawnee keep as security?','The borrower’s silver watch.','The borrower’s paycheck.','A page from the agreement only.','pawnee.s1 receives pledged property as security.'),Q(1,'Who is the pawnee in a pawn transaction?','The party receiving the pledge and lending money.','The party giving the item and borrowing money.','A shop customer who buys no goods.','The pawnee takes the pledge.'),Q(1,'Which role does not belong to the pawnee?','Handing over one’s watch to borrow money.','Holding a pledged watch as security.','Lending against the pledged property.','The first describes the pawnor, not the pawnee.'),Q(1,'What does -ee indicate in pawnee?','The person who receives the action or property.','The person who performs all actions.','A plural form of pawn.','The pawnee is the recipient of the pledge.','word-formation')]);
P('pay','From Old French paier, from Latin pacare “settle, appease”; it can mean give money, render what is owed or give attention/a visit, produce a benefit or cost, and money earned for work.',[C('pay.s1','金融','Customers can pay the repair bill online or at the counter before collecting their bicycles.','顾客可以在线上或柜台支付维修费，再取回自行车。','Customers can pay the repair bill / online or at the counter / before collecting / their bicycles.','pay.s1 指为商品、工作或债务付钱。','顾客向店铺支付维修费。'),C('pay.s2','通用','The ambassador paid a visit to the school and thanked the students for their welcome letters.','大使访问了学校，并感谢学生们寄来的欢迎信。','The ambassador paid a visit / to the school / and thanked the students / for their welcome letters.','pay.s2 可指偿还所欠之物，也可与 attention/visit 等搭配表示给予或进行。','pay a visit 是进行访问。'),C('pay.s3','通用','It pays to check the contract twice because a careful review can prevent expensive mistakes.','仔细检查合同两遍是值得的，因为认真审阅能避免昂贵的错误。','It pays to check the contract twice / because a careful review / can prevent / expensive mistakes.','pay.s3 可指产生好处、值得做，或承受某种结果。','检查合同能带来避免损失的好处。'),C('pay.s4','劳动','The job advert listed the weekly pay and explained when the first wage would arrive.','招聘广告列出了周薪，并说明第一笔工资何时到账。','The job advert listed the weekly pay / and explained / when the first wage / would arrive.','pay.s4 作名词，指因工作得到的工资。','招聘广告说明劳动报酬。')],M('The customer paid the bill by keeping the money and leaving the shop without settling the charge.','The customer paid the bill by transferring the required amount before collecting the bicycle.','不支付款项却称已付款，行为和叙述相矛盾。','meaning'),[Q(1,'What did customers pay before collecting their bicycles?','The repair bill.','The weekly wages.','A visit to the ambassador.','pay.s1 is money given for goods or services.'),Q(2,'What did the ambassador do at the school?','Paid a visit.','Paid the repair bill.','Received a weekly paycheck.','pay.s2 appears in the collocation pay a visit.'),Q(3,'Why does it pay to review the contract?','A careful review can prevent costly errors.','It guarantees a weekly wage.','It lets a customer avoid paying a bill.','pay.s3 means be beneficial or worthwhile.'),Q(4,'What did the job advert list?','The weekly wage.','A visiting schedule.','A pawned watch.','pay.s4 is money received for work.','distinction')]);
P('pay back','From pay + back; it means return borrowed money or, informally, take revenge on someone.',[C('pay back.s1','金融','I will pay back the loan in monthly installments, starting with the first payment next Friday.','我会分期偿还这笔贷款，第一笔款项下周五支付。','I will pay back the loan / in monthly installments / starting with the first payment / next Friday.','pay back.s1 指把借来的钱还回去。','借款人按期归还贷款。'),C('pay back.s2','社交','Rather than pay back the prank with another cruel trick, Jo told her friend honestly that it had hurt.','乔没有用另一个残酷恶作剧报复，而是坦诚告诉朋友那件事伤害了自己。','Rather than pay back the prank / with another cruel trick / Jo told her friend honestly / that it had hurt.','pay back.s2 口语中指因别人的坏行为而报复对方。','例句说明她选择不报复。')],M('I paid back the loan by keeping the borrowed money and refusing every installment.','I paid back the loan by returning the borrowed money in installments.','保留借款不还不是偿还。','meaning'),[Q(1,'How will the borrower pay back the loan?','In monthly installments.','By keeping all the borrowed money.','By buying a new bicycle.','pay back.s1 is returning borrowed money.'),Q(2,'What did Jo choose instead of paying back the prank?','She explained honestly that it had hurt her.','She played an even crueler trick.','She asked the bank for a loan.','pay back.s2 can mean retaliate; she chooses not to.'),Q(1,'Which sentence uses pay back for a debt?','I will pay back the borrowed $40 next week.','I will pay the cashier for dinner.','I will pay attention to the lecture.','The first explicitly returns borrowed money.'),Q(2,'Which action is paying someone back in the revenge sense?','A person deliberately retaliates for a harmful prank.','A borrower repays a loan.','A customer settles a bill.','The first is revenge rather than debt repayment.','distinction')]);
P('payable','From pay + -able; it describes money that must be paid at a stated time.',C('payable.s1','金融','The invoice shows the balance payable by 30 June, giving the client two weeks to arrange the transfer.','发票注明余额须在6月30日前支付，客户有两周时间安排转账。','The invoice shows the balance payable / by 30 June / giving the client two weeks / to arrange the transfer.','payable.s1 指须在规定时间支付的。','发票标明了付款期限。','word-formation'),M('The invoice marked the fully refunded amount payable even though no money remained due.','The invoice marked the unpaid balance payable by the stated deadline.','已全额退款的款项不再是需要支付的欠款。','distinction'),[Q(1,'When is the invoice balance payable?','By 30 June.','After it has been fully refunded.','Only if the client never receives the invoice.','payable.s1 means due to be paid at a stated time.'),Q(1,'Which amount is payable?','An unpaid balance due next week.','A bill already settled in full.','A refund already returned to the customer.','The first amount remains due.'),Q(1,'What does payable mean on an invoice?','Must be paid.','Has already been canceled.','Will never be collected.','The adjective describes an amount due.'),Q(1,'Which suffix signals ability or obligation in payable?','-able','-er','-ish','Payable is formed from pay + -able, meaning due to be paid.','word-formation')]);
P('paycheck','From pay + check; in American English it means money paid for work or the check on which wages are written.',[C('paycheck.s1','通用','After rent and groceries, she set aside part of her paycheck for the emergency fund.','付完房租和杂货钱后，她把部分工资存入应急基金。','After rent and groceries / she set aside part of her paycheck / for the emergency fund.','paycheck.s1 指劳动所得的工资，也可指写明工资的支票。','工资到账后，她留出一部分储蓄。'),C('paycheck.s1','通用','The new employee deposited her paper paycheck at the bank before paying the electricity bill.','新员工先把纸质工资支票存入银行，再缴电费。','The new employee deposited / her paper paycheck at the bank / before paying / the electricity bill.','paycheck.s1 也可指载有工资款项的支票。','纸质支票是支付工资的凭证。')],M('She called her paycheck unpaid wages even though the full salary had not yet been earned or issued.','She called the money issued for her completed work her paycheck.','尚未挣得或发放的款项不能说已经是工资支票/工资。','meaning'),[Q(1,'What did she save for emergencies?','Part of her wages.','A repair bill she still owed.','A parcel from the bookstore.','paycheck.s1 can mean money paid for work.'),Q(1,'What did the employee deposit?','A paper check carrying her wages.','A customer’s payment invoice.','A list of all employees.','paycheck.s1 also names the wage check.'),Q(1,'Which item is a paycheck?','Money an employer pays an employee for work.','A bill the employee must pay.','A list of store customers.','A paycheck is compensation for work.'),Q(1,'Why might paycheck mean either money or a document?','It names wages and the check used to issue them.','It always names a loan agreement.','It refers only to a time card.','The word covers both the pay and its check.','meaning')]);
P('payment','From pay + -ment; payment means the act of paying or the sum of money that is paid.',[C('payment.s1','金融','Payment by bank transfer is due when the repair shop returns the bicycle to its owner.','修理店把自行车还给车主时，须通过银行转账付款。','Payment by bank transfer / is due / when the repair shop / returns the bicycle to its owner.','payment.s1 指为某物付款的行为。','by bank transfer 说明付款方式。'),C('payment.s2','金融','The first payment of $120 covered one month of the equipment lease.','第一笔120美元的款项支付了一个月的设备租金。','The first payment of $120 / covered one month / of the equipment lease.','payment.s2 指已经支付的一笔钱。','120美元是实际支付金额。')],M('The shop recorded a payment even though the customer transferred no money and left the bill unpaid.','The shop recorded a payment after the customer transferred the agreed amount.','没有付钱时不能记录已完成的付款。','meaning'),[Q(1,'How was payment due at the repair shop?','By bank transfer.','By a public patrol.','By a patterned stone.','payment.s1 names the act of paying.'),Q(2,'What did the first payment of $120 cover?','One month of the lease.','The entire building forever.','A patrol group’s uniforms.','payment.s2 is a particular sum paid.'),Q(1,'Which sentence uses payment for the act?','Payment is required before the bicycle is released.','The payment was $120.','She received her paycheck.','The first describes the act/process of paying.'),Q(2,'Which is a payment as a sum?','A $35 transfer sent to the utility company.','The general act of sending money.','A policy about future billing.','The transfer is a specific sum paid.','distinction')]);
P('payroll','From pay + roll, a “roll” being a list of names; payroll can mean a company’s employee list or the total wages it pays.',[C('payroll.s1','劳动','The human-resources clerk updated the payroll when three new technicians joined the company.','三名新技师加入公司后，人事文员更新了在职人员名单。','The human-resources clerk updated the payroll / when three new technicians / joined the company.','payroll.s1 指公司雇用并支付工资的人员名单。','新增员工被加入公司名单。'),C('payroll.s2','金融','The company’s monthly payroll rose after it added a second shift at the factory.','工厂增加第二班后，公司的月工资总额上升了。','The company’s monthly payroll rose / after it added a second shift / at the factory.','payroll.s2 指支付给雇员的工资总额。','新增班次增加了工资总支出。')],M('The company’s payroll fell after it hired 40 additional employees and raised everyone’s wages.','The company’s payroll increased after it hired workers and raised wages.','增加员工和工资通常会增加工资总额，而非使其下降。','meaning'),[Q(1,'What did the clerk update?','The list of company employees.','The amount owed by one customer.','The employee’s personal paycheck only.','payroll.s1 means the list of people employed and paid.'),Q(2,'Why did the monthly payroll rise?','The factory added a second shift.','The company removed all wages.','The clerk deleted every employee.','payroll.s2 is the total wages paid.'),Q(1,'Which item is a company payroll in the roster sense?','The current list of its employees.','A single employee’s bank card.','A delivery schedule.','The roster meaning is the list of employees.'),Q(2,'Which figure is payroll in the total-cost sense?','The total wages paid to all employees this month.','The list of staff names.','One worker’s salary only.','Payroll can mean total compensation cost.','distinction')]);
P('pe','An abbreviation of physical education; it names the school subject involving exercise, movement, and sports skills.',C('pe.s1','教育','The class changed into sneakers before PE and practiced passing a ball safely in the gym.','体育课前，学生们换上运动鞋，并在体育馆练习安全传球。','The class changed into sneakers / before PE / and practiced passing a ball / safely in the gym.','pe.s1 是 physical education 的缩写，指学校体育课。','换运动鞋和练习运动技能体现体育课。','abbreviation'),M('The timetable labeled a silent written grammar exam as PE even though students did no physical activity.','The timetable labeled the gym lesson with movement and sports practice as PE.','没有体育活动的语法考试不是体育课。','meaning'),[Q(1,'What did students practice in PE?','Passing a ball in the gym.','Writing a grammar exam in silence.','Depositing a paycheck.','pe.s1 is physical education at school.'),Q(1,'What does PE stand for?','Physical education.','Pavilion exercise only.','Payment estimate.','PE is the abbreviation for physical education.'),Q(1,'Which activity is most likely part of PE?','Practicing safe movement and sports skills.','Reading a history essay at a desk only.','Calculating a payroll total.','PE involves physical activity and movement.'),Q(1,'Where did the class have PE?','In the gym.','At the bank.','On the legal pavement.','The gym context fits a school physical-education class.','context')]);
P('pea','From Middle English pease, from Old English pise, from Latin pisum and Greek pisos; pea is the singular form created after the older plural pease was reinterpreted.',C('pea.s1','饮食','A single pea rolled off the plate, and the child picked it up before it reached the floor.','一颗豌豆从盘子上滚落，孩子赶在它掉到地上前把它捡了起来。','A single pea rolled off the plate / and the child picked it up / before it reached the floor.','pea.s1 指长在豆荚里、作为蔬菜食用的小圆绿色种子。','句子明确是一颗单独的豌豆。','word-formation'),M('The recipe asked for peas, but the cook added a single peach instead.','The recipe asked for peas, and the cook added several green pea seeds.','桃子不是豌豆；配方要求的是豌豆种子。','confusable'),[Q(1,'What rolled off the plate?','A single green seed from a pea pod.','A whole peach with a large stone.','A pay slip.','pea.s1 is a small edible seed.'),Q(1,'Where do peas grow?','Inside a pod.','On a tree as large fruit.','On a paved road.','Pea seeds grow in pods.'),Q(1,'What is the usual plural of pea?','peas','peae','peases only','The modern plural is peas.'),Q(1,'Which ingredient is a pea?','A small round green vegetable seed.','A pink-orange color.','A fried flat patty.','The first describes a pea.','meaning')]);
P('peace','From Old French pais, from Latin pax, pacem; peace can mean no war, a calm state free from worry or noise, or a treaty/public order.',[C('peace.s1','政治','The two countries signed a ceasefire agreement and began a period of peace after years of fighting.','两国签署停火协议，结束多年战事，开始进入和平时期。','The two countries signed a ceasefire agreement / and began a period of peace / after years of fighting.','peace.s1 指没有战争或打斗的时期或关系。','停火使两国不再交战。'),C('peace.s2','通用','After the guests left, the house returned to peace and Mara could read beside the quiet fire.','客人离开后，家中恢复了安宁，玛拉可以在安静的炉火旁读书。','After the guests left / the house returned to peace / and Mara could read / beside the quiet fire.','peace.s2 指没有忧虑或噪音的平静状态。','安静环境让她重新放松。'),C('peace.s3','法律','The peace treaty formally ended the conflict, while local officials worked to maintain peace in the streets.','和平条约正式结束了冲突，当地官员则努力维护街区治安。','The peace treaty formally ended the conflict / while local officials worked / to maintain peace / in the streets.','peace.s3 指结束战争的和约，也可指公共秩序。','条约结束战事，官员维护治安。')],M('The countries remained at war with daily fighting, yet the report called their relationship a time of peace.','The countries entered a period of peace after the fighting stopped.','持续交战不符合没有战争或打斗的和平状态。','meaning'),[Q(1,'What began after the ceasefire?','A period without fighting between the countries.','A new military campaign.','A noisy family gathering.','peace.s1 is the absence of war.'),Q(2,'When did the house return to peace?','After the guests left and the room became quiet.','While the guests shouted in every room.','When a battle began outside.','peace.s2 is calm and quiet.'),Q(3,'What did the peace treaty do?','It formally ended the conflict.','It extended the fighting.','It listed café patrons.','peace.s3 includes a treaty ending war.'),Q(3,'What did local officials try to maintain?','Public order in the streets.','A quiet house for reading.','A ceasefire between the two nations only.','peace.s3 can also mean public order.','distinction')]);
P('peaceful','From peace + -ful; it describes a situation without war or one that is calm and quiet.',[C('peaceful.s1','社会','The peaceful village meeting ended with a written agreement and no shouting or threats.','平静的村民会议以书面协议结束，没有争吵或威胁。','The peaceful village meeting / ended with a written agreement / and no shouting / or threats.','peaceful.s1 指没有战争，或平静安宁的。','会议没有冲突并达成协议。','word-formation'),C('peaceful.s1','通用','They spent a peaceful afternoon reading under the trees beside the lake.','他们在湖边树下度过了一个宁静的下午，静静地读书。','They spent a peaceful afternoon / reading under the trees / beside the lake.','peaceful.s1 也可指安静、没有打扰的。','树下读书的环境安宁。','word-formation')],M('The peaceful meeting was full of threats, shouting, and physical fights.','The peaceful meeting ended through calm discussion without threats or fighting.','威胁和打斗与 peaceful 的无冲突含义相反。','meaning'),[Q(1,'How did the village meeting end?','With an agreement and no threats or shouting.','With a fight and broken furniture.','With a noisy battle.','peaceful.s1 describes a calm meeting without conflict.'),Q(1,'What did they do during the peaceful afternoon?','Read quietly beside the lake.','Argue loudly under the trees.','Work through a military conflict.','The quiet reading setting is peaceful.'),Q(1,'Which place is peaceful?','A quiet garden with no conflict or disturbance.','A street during a violent battle.','A room filled with shouting.','The garden is calm and quiet.'),Q(1,'What does -ful contribute in peaceful?','Having or characterized by peace.','Without peace.','A person who makes payments.','-ful means full of or characterized by peace.','word-formation')]);
P('peacefully','From peaceful + -ly; it is an adverb meaning without noise, conflict, or disturbance.',C('peacefully.s1','通用','The children played peacefully in the next room while their grandparents talked in the garden.','孩子们在隔壁房间安静地玩耍，祖父母则在花园里聊天。','The children played peacefully / in the next room / while their grandparents talked / in the garden.','peacefully.s1 表示没有喧闹、冲突或打扰地。','孩子们安静玩耍，没有打扰交谈。','word-formation'),M('The neighbors resolved the dispute peacefully by shouting threats and breaking one another’s windows.','The neighbors resolved the dispute peacefully by talking calmly and agreeing on a solution.','威胁和破坏不是和平解决。','distinction'),[Q(1,'How did the children play?','Quietly without disturbing the adults.','By fighting and shouting.','By leaving the house in a hurry.','peacefully.s1 means without disturbance.'),Q(1,'Which action resolves a dispute peacefully?','Listening and agreeing on a nonviolent solution.','Threatening the other side.','Breaking windows.','The first avoids conflict and disturbance.'),Q(1,'What does peacefully modify in the example?','The way the children played.','The grandparents’ age.','The room’s paint color.','The adverb describes how they played.'),Q(1,'How is peacefully formed?','peaceful + -ly','peace + plural -s','peach + -ful','-ly makes an adverb from peaceful.','word-formation')]);
P('peacetime','From peace + time; it names a period when a country is not at war.',C('peacetime.s1','政治','During peacetime, the government shifted some military factories to producing buses and farm equipment.','和平时期，政府把部分军工厂转为生产公交车和农用设备。','During peacetime / the government shifted some military factories / to producing buses / and farm equipment.','peacetime.s1 指没有战争的时期。','工厂在无战事时转向民用生产。','word-formation'),M('The history book called the years of active battles peacetime even though the country was at war throughout.','The history book described the years without war as peacetime.','持续交战不属于没有战争的时期。','meaning'),[Q(1,'What did the government do during peacetime?','Shifted some factories to civilian production.','Prepared to report a battle as over.','Stopped producing all goods.','peacetime.s1 is a period without war.'),Q(1,'Which period is peacetime?','Years when no war is taking place.','A week of active fighting.','An afternoon without loud music only.','The word refers specifically to the absence of war.'),Q(1,'What does peacetime contrast with?','Wartime.','A workday.','A pageant.','Peacetime is the period without war.'),Q(1,'How is peacetime formed?','peace + time','peace + -ly','pea + -time','It combines peace and time to name a nonwar period.','word-formation')]);
P('peach','From Middle English peche, from Old French pesche and Latin persica “Persian (fruit)”; peach names a soft, sweet stone fruit and its pinkish-orange color.',[C('peach.s1','饮食','The ripe peach had soft yellow flesh, red-blushed skin, and a large stone in the center.','成熟的桃子果肉柔软、呈黄色，果皮带红晕，中心有一颗大核。','The ripe peach / had soft yellow flesh / red-blushed skin / and a large stone in the center.','peach.s1 指皮色黄或红、果肉柔软香甜且有大核的圆形水果。','大核和柔软果肉是桃子的特征。'),C('peach.s2','色彩','The designer chose a pale peach color for the nursery walls, warmer than pink but lighter than orange.','设计师为婴儿房墙壁选了浅桃色，比粉色暖、又比橙色淡。','The designer chose a pale peach color / for the nursery walls / warmer than pink / but lighter than orange.','peach.s2 指带粉的橙色，即桃色。','墙面颜色介于粉和橙之间。')],M('The menu described a ripe peach as a hard green vegetable with no sweet flesh or stone.','The menu described a ripe peach as a soft, sweet fruit with a large stone.','硬质绿色蔬菜与桃子的特征不符。','meaning'),[Q(1,'What was in the center of the ripe peach?','A large stone.','A seed pod full of peas.','A paper payment slip.','peach.s1 is a stone fruit.'),Q(2,'What shade did the designer choose?','A pinkish-orange color.','A deep blue.','A bright leaf green.','peach.s2 names a soft pink-orange color.'),Q(1,'Which item is a peach?','A soft, sweet fruit with a central stone.','A small green seed in a pod.','A kind of hard roadway.','The first describes the fruit.'),Q(2,'Which wall color is peach?','A warm, light pink-orange.','A dark purple.','A neutral gray.','The peach color is pinkish-orange.','meaning')]);
P('peacock','From Middle English pecok, formed from pea (a shortened form of peafowl) + cock; it names the male peafowl and figuratively a vain show-off, and can be a verb meaning strut ostentatiously.',[C('peacock.s1','生物','The male peacock spread his iridescent tail beside the path to attract a female.','雄孔雀在小路旁展开虹彩尾羽，以吸引雌孔雀。','The male peacock spread his iridescent tail / beside the path / to attract a female.','peacock.s1 指雄孔雀，也可比喻爱卖弄自己的人。','展开尾羽是雄孔雀的展示行为。'),C('peacock.s1','口语','At the reception, the peacock in the gold jacket kept steering every conversation back to his expensive watch.','晚宴上，那个穿金色夹克的爱炫耀者总把每次谈话都扯回自己的名表。','At the reception / the peacock in the gold jacket / kept steering every conversation / back to his expensive watch.','peacock.s1 比喻爱卖弄自己、吸引注意的人。','他反复炫耀名表。'),C('peacock.s2','通用','The actor peacocked across the lobby in a bright cape, hoping every guest would notice him.','演员穿着鲜艳披风招摇地走过大厅，希望每位客人都注意到他。','The actor peacocked across the lobby / in a bright cape / hoping every guest / would notice him.','peacock.s2 作动词，指以招摇虚荣的方式行走或表现。','他的走姿刻意引人注目。')],M('The bird was identified as a peacock because it was a female peafowl with no male plumage.','The bird was identified as a peahen because it was female.','peacock 指雄孔雀；雌性称 peahen。','meaning'),[Q(1,'What did the male peacock spread?','Its iridescent tail.','A bright cape.','A gold jacket.','peacock.s1 is the male peafowl.'),Q(1,'Why was the man called a peacock at the reception?','He kept showing off his expensive watch.','He quietly avoided every conversation.','He was studying birds for a class.','peacock.s1 can figuratively mean a vain show-off.'),Q(2,'How did the actor peacock across the lobby?','He walked ostentatiously to attract attention.','He hid behind a curtain.','He examined the guest list quietly.','peacock.s2 is the verb for showy, vain behavior.'),Q(1,'Which bird is a peacock?','A male peafowl displaying its colorful tail.','A female peahen only.','A black-and-white shellfish-eating shorebird.','Peacock names the male bird.','distinction')]);
P('peak','Origin uncertain; peak names a pointed summit or highest level, and is also used as a verb and adjective for reaching or occurring at that high point.',[C('peak.s1','地理','A narrow trail led the climbers to the peak, where they could see the valley on every side.','一条狭窄小径把登山者带到山顶，他们可以从那里四面俯瞰山谷。','A narrow trail led the climbers / to the peak / where they could see / the valley on every side.','peak.s1 指山的尖顶或其他尖的顶部。','山顶是山体的最高尖端。'),C('peak.s2','通用','The café reaches its peak in customer traffic just after the nearby offices close.','附近办公室下班后不久，这家咖啡馆的客流达到高峰。','The café reaches its peak in customer traffic / just after / the nearby offices close.','peak.s2 指最高水平或最忙的时段。','顾客数量在那时达到最高。'),C('peak.s3','科学','The temperature peaked at 38 degrees in the afternoon and fell after sunset.','气温下午达到38度的最高点，日落后开始下降。','The temperature peaked at 38 degrees / in the afternoon / and fell / after sunset.','peak.s3 作动词，指达到最高点或最大值。','达到38度后温度下降。'),C('peak.s4','商业','The airline charges peak fares during the holiday period, when demand for seats is highest.','假期期间座位需求最高，航空公司会收取高峰票价。','The airline charges peak fares / during the holiday period / when demand for seats / is highest.','peak.s4 作形容词，指发生在最忙时段或处于最高水平的。','票价对应需求最高的时段。')],M('The graph showed sales continuing to rise for months, but the report said they had already peaked and were falling.','The report said sales peaked when they reached their highest level and then began to fall.','仍持续上升的数据不能同时说明已经达到峰值并下降。','meaning'),[Q(1,'Where did the climbers arrive?','At the mountain’s pointed summit.','At the busiest hour in the café.','At a ticket counter.','peak.s1 is a mountain top.'),Q(2,'When does the café reach its peak in traffic?','Just after nearby offices close.','Before the offices open, when no one is nearby.','Only during the quietest hour.','peak.s2 can mean the busiest period.'),Q(3,'What happened to the temperature?','It reached 38 degrees and then fell.','It stayed at zero all afternoon.','It reached its highest point after sunset.','peak.s3 means reach the maximum level.'),Q(4,'What are peak fares?','Higher fares charged when seat demand is greatest.','Refunds paid after travel.','Tickets for a mountain climb.','peak.s4 is an adjective for the busiest/highest-demand time.','distinction')]);
P('peal','From Middle English peal, possibly influenced by bell-ringing terms; it means a loud prolonged ringing or burst of sound, and as a verb to ring loudly.',[C('peal.s1','通用','A peal of bells rang across the square when the town’s celebration began.','镇上的庆典开始时，一阵响亮的钟声传遍广场。','A peal of bells rang / across the square / when the town’s celebration began.','peal.s1 作名词，指响亮而持续的钟声，也可指一阵雷声或笑声。','多口钟同时鸣响形成一阵持续声响。'),C('peal.s2','通用','The church bells pealed at noon, and people stopped briefly to listen from the market street.','正午时教堂钟声大作，市场街上的人们短暂停下来聆听。','The church bells pealed / at noon / and people stopped briefly / to listen from the market street.','peal.s2 作动词，指响亮地鸣响或发出声音。','钟在正午响亮鸣响。')],M('The bells pealed silently at noon, producing no sound for people in the square to hear.','The bells pealed loudly at noon, sending a clear ringing across the square.','没有声音就不能称为响亮鸣响。','meaning'),[Q(1,'What began the town celebration?','A loud ringing of bells.','A quiet letter from the mayor.','A small piece of pavement.','peal.s1 is a burst or prolonged ringing.'),Q(2,'What did the church bells do at noon?','They rang loudly.','They fell from the tower.','They remained silent.','peal.s2 means ring or sound loudly.'),Q(1,'Which sound could be a peal?','A burst of thunder rolling over the valley.','A silent page being turned.','A low whisper inaudible to anyone.','A peal can be a loud burst of thunder.'),Q(2,'Which sentence uses peal as a verb?','The bells pealed across the village.','A peal of laughter filled the room.','The peal lasted for several seconds.','The first uses pealed as an action.','grammar')]);
P('peanut','A compound of pea + nut; it names an oval edible seed that grows underground, and in the plural “peanuts” can mean a very small amount of money.',[C('peanut.s1','饮食','The farmer dug carefully beneath the plants and found peanuts developing underground in their pods.','农夫小心地在植株下挖掘，发现花生正在地下的豆荚中生长。','The farmer dug carefully beneath the plants / and found peanuts / developing underground / in their pods.','peanut.s1 指长在地下、可烤或烹煮食用的椭圆形种子。','地下豆荚里长出花生果实。'),C('peanut.s2','口语','The seasonal worker said the harvest wage was peanuts compared with the hours spent in the field.','这名季节工说，与在田里工作的时长相比，收获季工资少得可怜。','The seasonal worker said / the harvest wage was peanuts / compared with the hours / spent in the field.','peanut.s2 复数口语中指很少的钱。','工资与工时相比微不足道。')],M('The worker called a million-dollar bonus peanuts even though it was an enormous amount for the job.','The worker called the tiny hourly wage peanuts because it was far below a fair rate.','金额巨大时称 peanuts 与“少得可怜”不符。','meaning'),[Q(1,'Where were the peanuts growing?','Underground in pods.','On a tall tree branch.','Inside a stone fruit.','peanut.s1 is an edible seed that grows underground.'),Q(2,'What did the worker mean by “the wage was peanuts”?','It was a very small amount of money.','It was paid in actual nuts.','It was the highest wage available.','peanut.s2 is informal for a tiny amount of money.'),Q(1,'Which food is a peanut?','An oval seed that develops underground.','A fruit with yellow flesh and a large stone.','A small green seed inside a garden pod.','The first specifically describes a peanut.'),Q(2,'Which salary could be called peanuts?','A tiny wage far below the hours required.','A large bonus that exceeds the annual salary.','A fair wage agreed by both parties.','Peanuts means a very small amount of money.','meaning')]);
P('pear','From Old English pere, borrowed from Latin pirum “pear,” ultimately related to Greek apion; it is a sweet, juicy fruit, usually green or yellow and narrow near the stem.',C('pear.s1','饮食','She sliced a ripe green pear over the salad, adding its sweet juice to the bitter leaves.','她把成熟的绿梨切片放在沙拉上，让甜汁中和苦味叶菜。','She sliced a ripe green pear / over the salad / adding its sweet juice / to the bitter leaves.','pear.s1 指通常绿色或黄色、底部较圆而近蒂处较窄的甜汁水果。','梨切片后与沙拉搭配。','word-formation'),M('The recipe called for a pear, but the cook added a hard, salty mineral instead.','The recipe called for a ripe, juicy pear.','矿物不是水果，无法替代配方里的梨。','meaning'),[Q(1,'What fruit did she slice over the salad?','A ripe green pear.','A peanut growing underground.','A peach-colored wall.','pear.s1 is a sweet juicy fruit.'),Q(1,'Which shape is typical of a pear?','Narrow near the stem and rounder at the base.','Flat and square like a tile.','Long and pointed at both ends.','The source sense describes the pear’s narrow-top shape.'),Q(1,'What did the pear add to the salad?','Sweet juice.','A loud ringing sound.','A legal agreement.','The fruit’s juice added sweetness.'),Q(1,'Which item is a pear?','A green or yellow juicy fruit.','A small flat meat cake.','A male peafowl.','The first is the fruit named pear.','meaning')]);
P('pearl','From Old French perle, probably from a Mediterranean/Latin form; pearl names the hard jewel formed inside some mollusks and figuratively something rare or excellent.',[C('pearl.s1','饰品','The jeweler examined a small white pearl that had formed inside an oyster shell.','珠宝商检查了一颗在牡蛎壳内形成的小白珍珠。','The jeweler examined / a small white pearl / that had formed / inside an oyster shell.','pearl.s1 指通常在牡蛎等贝壳内形成、用作珠宝的硬圆珠。','珍珠在贝类内部形成。'),C('pearl.s2','比喻','The editor called the brief final sentence a pearl of wisdom because it expressed the whole lesson clearly.','编辑称最后那句简短的话是智慧的珍品，因为它清楚表达了整堂课的要义。','The editor called the brief final sentence / a pearl of wisdom / because it expressed / the whole lesson clearly.','pearl.s2 可比喻珍珠般的东西，或稀有而出色的事物。','这句话简练而有价值。')],M('The jeweler described a common plastic bead as a natural pearl formed inside an oyster.','The jeweler described the hard bead formed inside the oyster shell as a pearl.','塑料珠并非牡蛎中形成的天然珍珠。','meaning'),[Q(1,'Where did the jeweler’s pearl form?','Inside an oyster shell.','Inside a pea pod.','On a tree branch.','pearl.s1 is formed inside a mollusk shell.'),Q(2,'Why did the editor call the sentence a pearl of wisdom?','It was a concise, excellent expression of the lesson.','It was made from oyster shell.','It was a long list with no clear point.','pearl.s2 figuratively means something rare and excellent.'),Q(1,'Which item is a natural pearl?','A hard jewel formed inside a mollusk.','A plastic craft bead.','A smooth pebble worn by water.','Natural pearls form inside some mollusks.'),Q(2,'Which phrase uses pearl figuratively?','That short insight was a pearl.','The jeweler polished the pearl.','An oyster produced a pearl.','The first treats pearl as a rare excellent thing.','distinction')]);
P('pearly','From pearl + -y; it describes a soft white shine like that of a pearl.',C('pearly.s1','通用','The early light gave the clouds a pearly sheen, soft and white rather than bright silver.','晨光让云层泛出珍珠般柔和的白色光泽，而非明亮的银色。','The early light gave the clouds / a pearly sheen / soft and white / rather than bright silver.','pearly.s1 指具有珍珠般柔和白亮光泽的。','光泽柔和、近白而似珍珠。','word-formation'),M('The clouds had a dull black surface with no soft white shine, but the report described them as pearly.','The clouds had a soft white shine and looked pearly in the morning light.','暗黑且没有光泽不符合 pearly。','meaning'),[Q(1,'What kind of sheen did the clouds have?','A soft, pearl-like white shine.','A dull black surface.','A sharp metallic ring.','pearly.s1 means shining softly like a pearl.'),Q(1,'Which surface looks pearly?','A softly glowing white shell.','A flat matte black wall.','A rough, unlit stone.','The shell has a pearl-like sheen.'),Q(1,'What does pearly describe?','A soft white shine like a pearl.','A loud burst of sound.','A small amount of money.','The adjective is about a pearl-like appearance.'),Q(1,'How is pearly formed?','pearl + -y','pear + -ful','peal + -ly','-y forms an adjective from pearl.','word-formation')]);
P('peart','An English/Scots dialect adjective of uncertain origin; it means brisk, cheerful, and alert.',C('peart.s1','方言','Despite the cold morning, the peart farmhand greeted everyone cheerfully and started work at once.','尽管清晨寒冷，这位精神爽快的农场工人仍愉快地和大家打招呼，立刻开始工作。','Despite the cold morning / the peart farmhand greeted everyone cheerfully / and started work / at once.','peart.s1 是方言用语，指轻快、愉快而机敏的。','他精神饱满、动作利落且心情愉快。','register'),M('The peart worker could barely stay awake, moved sluggishly, and refused to respond to anyone.','The peart worker was cheerful, alert, and quick to begin the day.','迟钝、困倦与 peart 所指的精神爽快相反。','distinction'),[Q(1,'How did the peart farmhand behave?','Cheerfully and energetically.','Sleepily and sluggishly.','Angrily and without speaking.','peart.s1 means brisk, cheerful, and alert.'),Q(1,'Which person could be described as peart?','An alert, upbeat person who gets moving quickly.','A person too tired to answer.','A person who hides from every task.','The first person is brisk and cheerful.'),Q(1,'What is peart’s register?','Dialectal.','A standard chemical term.','A legal title for a lender.','The source marks peart as dialect.'),Q(1,'Which word is closest in meaning to peart?','lively','lethargic','hostile','Peart describes cheerful alertness.','meaning')]);
P('peasant','From Old French paisant “country dweller,” from pais “country”; it can mean a small-scale rural farmer, and when used as an insult, a rude or uneducated person.',[C('peasant.s1','农业','The novel’s peasant family grew barley on a small plot and relied on the harvest to pay their rent.','小说中的农民家庭在一小块土地上种大麦，靠收成支付租金。','The novel’s peasant family grew barley / on a small plot / and relied on the harvest / to pay their rent.','peasant.s1 指住在乡下并耕种小块土地的人，尤见于过去或贫困地区。','小块土地和依靠收成为生符合此义。'),C('peasant.s2','用法','Calling a diner a peasant because of a simple meal would be insulting, so the writer described the food choice without judging the person.','因为一顿简单饭菜就称食客为“没教养的人”会带有侮辱性，因此作者只描述食物选择，不评判对方。','Calling a diner a peasant / because of a simple meal / would be insulting / so the writer described the food choice without judging the person.','peasant.s2 作贬义称呼，指粗鲁或没有教养的人；用于人时具有侮辱性。','例句明确指出该称呼的贬义和侮辱效果。','register')],M('The article called a rural farmer a peasant as a neutral compliment and said the word could never insult anyone.','The article used peasant carefully for a small-scale rural farmer and noted that the insult sense is derogatory.','该词也可作贬义侮辱语，不能说永远中性。','register'),[Q(1,'What did the novel’s peasant family grow?','Barley on a small plot.','Pear trees in a city park.','Peafowl feathers.','peasant.s1 is a rural small-scale farmer.'),Q(2,'Why can calling a diner a peasant be insulting?','It can imply the person is rude or uneducated.','It means the diner owns a farm.','It is a formal title of respect.','peasant.s2 is derogatory when used as an insult.'),Q(1,'Which person fits the rural-farmer sense?','Someone farming a small plot in the countryside.','A city lawyer who never farms.','A patron who funds a theater.','The first matches peasant.s1.'),Q(2,'How should a writer handle peasant as an insult?','Recognize that it is derogatory and avoid casual labeling.','Use it as a neutral compliment for any diner.','Use it only for a payment list.','The insulting sense carries negative judgment.','register')]);
P('peat','From Middle English peat, of uncertain further origin; it is dark, spongy material formed in bogs and used as fuel or mixed into garden soil.',C('peat.s1','地理','The gardener mixed peat into the sandy bed to help it retain moisture for the new seedlings.','园丁把泥炭混入沙质花床，帮助它为新秧苗保持水分。','The gardener mixed peat / into the sandy bed / to help it retain moisture / for the new seedlings.','peat.s1 指沼泽形成的深色海绵状物质，可作燃料或混入土壤。','泥炭被加入园土以保湿。'),M('The gardener added a clear liquid fertilizer and called the liquid peat, even though it was not bog material.','The gardener added dark, spongy peat to the soil.','透明液体肥料不是沼泽中形成的泥炭。','meaning'),[Q(1,'Why did the gardener mix peat into the soil?','To help the bed retain moisture.','To make the soil ring loudly.','To create a road pavement.','peat.s1 can be mixed into garden soil.'),Q(1,'Where does peat form?','In bogs.','Inside a pearl oyster.','On a peach tree.','Peat is formed in boggy ground.'),Q(1,'Which material is peat?','Dark, spongy bog material.','A clear liquid with no solid matter.','A small rounded fruit.','Peat has a dark, spongy texture.'),Q(1,'What are two uses for peat?','Fuel and soil amendment.','A necklace and a music instrument.','A paycheck and a page.','Peat can be burned as fuel or mixed into soil.','meaning')]);
P('pebble','From Middle English pebble, perhaps related to a Low German word for small stones; the precise origin is uncertain. A pebble is a small smooth stone worn by water.',C('pebble.s1','自然','A smooth pebble from the riverbed fit in her palm, its edges rounded by years of flowing water.','一块从河床捡来的光滑小石子刚好能握在她手里，边缘被多年的流水磨圆。','A smooth pebble from the riverbed / fit in her palm / its edges rounded / by years of flowing water.','pebble.s1 指被水冲磨光滑的小石子。','河水长期磨圆了石子的边缘。'),M('The child called a large jagged boulder a pebble even though it could not be lifted by hand.','The child called the small smooth stone worn by the stream a pebble.','巨大且棱角锋利的巨石不符合小而光滑的 pebble。','meaning'),[Q(1,'What had rounded the pebble’s edges?','Years of flowing water.','A coat of paint.','A loud peal of bells.','pebble.s1 is a small stone worn smooth by water.'),Q(1,'Which object is a pebble?','A small smooth stone from a riverbed.','A large jagged boulder.','A flat concrete road.','The first matches the size and smoothness of a pebble.'),Q(1,'What does a pebble feel like in the example?','Small and smooth enough to fit in a palm.','Huge and impossible to lift.','Soft like a pillow.','The context describes a rounded small stone.'),Q(1,'Where did the pebble come from?','A riverbed.','A peach orchard.','A theater stage.','The riverbed is the source in the example.','context')]);
P('peck','Of imitative Middle English origin, perhaps echoing a bird’s quick beak strike; peck can mean strike/eat with a beak, give a quick light kiss, or as a noun name a peck or a peck measure/large amount.',[C('peck.s1','动物','The hen pecked at the grain scattered near the coop until the ground was clean.','母鸡啄食鸡舍附近撒落的谷粒，直到地面干净。','The hen pecked at the grain / scattered near the coop / until the ground / was clean.','peck.s1 指用喙击打或啄起食物。','母鸡用喙啄食地上的谷粒。'),C('peck.s2','口语','Before leaving for work, he gave his partner a quick peck on the cheek.','上班前，他在伴侣脸颊上轻轻快速地吻了一下。','Before leaving for work / he gave his partner / a quick peck / on the cheek.','peck.s2 指轻而快地吻一下。','quick peck 是轻快的一吻。'),C('peck.s3','通用','The baker bought a peck of apples for the festival pies, enough fruit for several large batches.','面包师为节庆馅饼买了一大筐苹果，足够做几大批。','The baker bought a peck of apples / for the festival pies / enough fruit / for several large batches.','peck.s3 作名词，可指一次啄、轻吻，或旧制容量单位/一大份。','a peck of apples 指很多苹果。')],M('The hen pecked at the grain by swallowing each kernel whole without touching it with her beak.','The hen pecked at the grain by striking and picking it up with her beak.','peck at food 是用喙啄食，完全不碰谷粒与动作矛盾。','meaning'),[Q(1,'What did the hen do to the grain?','She picked it up with her beak.','She kissed it lightly.','She measured the coop.','peck.s1 is the bird action of striking or picking food with the beak.'),Q(2,'What did he give his partner?','A quick, light kiss on the cheek.','A large bag of apples.','A sharp beak strike.','peck.s2 is a light quick kiss.'),Q(3,'How many apples did the baker buy?','A peck, enough for several large batches.','Exactly one apple.','A single grain.','peck.s3 can name a peck measure or a large amount.'),Q(1,'Which action is a bird pecking?','A hen taps a seed with its beak.','A dog paws at a gate.','A bell rings across town.','Pecking uses the beak to strike or pick food.','meaning')]);
P('pecking order','From peck + -ing + order, named after dominance relations observed in birds; it means a hierarchy ranking people or animals by power.',C('pecking order.s1','社会','The new team learned the informal pecking order by noticing whose decisions everyone followed during a crisis.','新团队通过观察危机中大家听从谁的决定，了解了非正式的等级秩序。','The new team learned / the informal pecking order / by noticing whose decisions / everyone followed during a crisis.','pecking order.s1 指人或动物按权力高低排列的等级制度。','决策影响力显示团队中的层级。','word-formation'),M('The group had no differences in authority, influence, or rank, but the report described a strict pecking order.','The report described a pecking order because some members had more authority and influence than others.','若成员没有任何权力或地位差异，就不存在等级排序。','meaning'),[Q(1,'How did the new team identify its pecking order?','They noticed whose decisions others followed.','They counted how many birds were present.','They measured each member’s height.','pecking order.s1 ranks members by power or influence.'),Q(1,'Which workplace has a pecking order?','A group where some roles have more authority than others.','A team with no hierarchy or status differences.','A set of unrelated visitors in a line.','A hierarchy ranks people by power.'),Q(1,'What does pecking order mean?','A ranking system based on power or status.','A method for feeding chickens only.','An order to buy a peck of fruit.','The phrase is figurative for hierarchy.'),Q(1,'Why is “pecking” part of the phrase’s origin?','It recalls dominance behavior observed among birds.','It means a bird kisses another bird.','It names a court payment.','The expression was inspired by birds’ dominance behavior.','word-formation')]);
P('peculate','From Latin peculari “to embezzle,” from peculium “private property”; it means steal or misuse funds entrusted to one’s care.',C('peculate.s1','法律','The auditor found that the treasurer had peculated money from the disaster fund entrusted to her office.','审计员发现，财务主管侵吞了交由其办公室保管的救灾基金。','The auditor found / that the treasurer had peculated money / from the disaster fund / entrusted to her office.','peculate.s1 指侵吞自己受托保管的钱款。','救灾基金由财务主管保管，却被其挪用。','word-formation'),M('The treasurer was accused of peculating funds even though every dollar remained accounted for and no money was taken.','The treasurer was accused of peculating funds after transferring entrusted money into a private account.','没有挪用或盗取资金时，peculate 的指控不成立。','meaning'),[Q(1,'What had the treasurer peculated?','Money from the disaster fund.','A package of seeds.','A pearl from an oyster.','peculate.s1 means embezzle entrusted funds.'),Q(1,'Which act is peculation?','A clerk steals money they were hired to manage.','A customer pays an invoice.','An auditor reports every transaction accurately.','The first is misuse of entrusted money.'),Q(1,'What does peculate mean?','Embezzle funds in one’s care.','Pay a debt honestly.','Give a quick kiss.','The verb specifically refers to stealing entrusted funds.'),Q(1,'What kind of money is involved in the example?','Funds entrusted to the treasurer’s office.','A personal gift with no conditions.','A worker’s legitimate paycheck.','The funds were under the treasurer’s care.','meaning')]);
P('peculiar','From Latin peculiaris “of one’s own, private,” from peculium “private property”; it can mean strange or uniquely belonging to one person, group, or place.',[C('peculiar.s1','通用','A peculiar tapping sound came from inside the wall, although the repair crew found no pipe or loose panel.','墙里传来一种奇怪的敲击声，但维修人员没有发现水管或松动的墙板。','A peculiar tapping sound / came from inside the wall / although the repair crew / found no pipe or loose panel.','peculiar.s1 指奇怪、出乎预料的。','墙内异响无法解释，因此显得奇怪。'),C('peculiar.s2','书面','The blue markings are peculiar to this species and do not appear on any other local butterfly.','这些蓝色斑纹是该物种独有的，在当地其他蝴蝶身上都没有。','The blue markings are peculiar to this species / and do not appear / on any other local butterfly.','peculiar.s2 指特属于某个人、群体或地方的。','斑纹只属于这一物种。')],M('The tapping sound was called peculiar even though it was the ordinary clock striking at the expected hour.','The unexplained tapping behind the wall was described as peculiar.','正常钟声按时响起并不反常；无法解释的墙内敲击才显奇怪。','distinction'),[Q(1,'Why did the tapping sound seem peculiar?','The crew could not find its source.','It was an ordinary clock at the expected time.','The repair crew caused it deliberately.','peculiar.s1 means strange or unexpected.'),Q(2,'What is peculiar to this butterfly species?','Its blue markings.','The local weather.','Every butterfly’s wings.','peculiar.s2 means uniquely belonging to one group.'),Q(1,'Which event is peculiar?','A wall makes unexplained tapping noises at midnight.','A clock rings at its usual scheduled hour.','A light turns on when its switch is pressed.','The unexplained noise is unexpected.'),Q(2,'Which phrase uses peculiar to mean “unique”?','This custom is peculiar to the island.','That was a peculiar sound in the wall.','He had a peculiar mood today.','The first says the custom belongs especially to the island.','distinction')]);
P('peculiarity','From peculiar + -ity; it names an odd habit or a feature especially characteristic of someone or something.',C('peculiarity.s1','通用','One peculiarity of the old clock was that it chimed once at noon and twice at midnight.','这座旧钟的一个特别之处是中午鸣一次，午夜鸣两次。','One peculiarity of the old clock / was that it chimed once at noon / and twice / at midnight.','peculiarity.s1 指古怪习惯或某人、某物特有的特征。','特殊报时方式是这座钟独有的特征。','word-formation'),M('The clock chimed exactly once every hour like every other clock, but the report described this ordinary behavior as a peculiarity.','The clock’s unusual pattern of chiming once at noon and twice at midnight was a peculiarity.','完全普通且普遍的行为不是特别之处。','meaning'),[Q(1,'What was unusual about the old clock?','It chimed once at noon and twice at midnight.','It never made any sound.','It showed the same time as every other clock.','peculiarity.s1 names a distinctive feature.'),Q(1,'Which is a peculiarity of a person?','An unusual habit unique to that person.','A routine shared by everyone in the group.','A payment due next week.','The first is an odd personal habit.'),Q(1,'What does peculiarity mean?','An odd habit or distinctive feature.','A regular wage list.','A peaceful agreement between nations.','The noun names a special or unusual trait.'),Q(1,'What is peculiarity formed from?','peculiar + -ity','pearl + -y','patron + -age','-ity makes a noun naming a quality or trait.','word-formation')]);
P('peculiarly','From peculiar + -ly; it means in a strange way or to a special degree.',[C('peculiarly.s1','通用','The door opened peculiarly, moving inward even though the hinges and frame appeared undamaged.','这扇门打开的方式很奇怪，尽管合页和门框看起来都完好无损。','The door opened peculiarly / moving inward / even though the hinges / and frame appeared undamaged.','peculiarly.s1 指以奇怪、反常的方式。','门的动作与正常预期不同。'),C('peculiarly.s1','通用','This valley is peculiarly suited to growing pears because its soil drains well and spring frosts are rare.','这个山谷特别适合种梨，因为土壤排水良好，春霜也很少。','This valley is peculiarly suited / to growing pears / because its soil drains well / and spring frosts are rare.','peculiarly.s1 也可表示格外、特别地。','该地条件尤其适宜种梨。')],M('The door opened peculiarly in a completely ordinary way, exactly as every other door did and with no unusual movement.','The door opened peculiarly by swinging inward despite being designed to open outward.','毫无异常的动作不能称为奇怪地打开。','meaning'),[Q(1,'How did the door open?','In an unexpected inward direction.','In the ordinary direction shown by its hinges.','It remained completely closed.','peculiarly.s1 can mean in a strange way.'),Q(1,'Why is the valley peculiarly suited to pears?','Its soil drains well and spring frosts are rare.','It is unusually cold and waterlogged.','It has no pear trees or suitable land.','Here peculiarly means especially or to a special degree.'),Q(1,'Which action happens peculiarly?','A light switch makes the room brighter when turned off.','A light turns on when its switch is pressed.','A clock rings at its scheduled hour.','The first is unexpected and odd.'),Q(1,'Which phrase is closest to peculiarly in the valley sentence?','especially well','in a strange manner only','never','In this context peculiarly means especially.','distinction')]);
P('pecuniary','From Latin pecuniarius, from pecunia “money,” historically related to pecus “cattle”; it means connected with money, especially fines, loss, or gain.',C('pecuniary.s1','法律','The court ordered pecuniary compensation for the damaged equipment and listed the amount in the judgment.','法院命令就受损设备给予金钱赔偿，并在判决中列明金额。','The court ordered pecuniary compensation / for the damaged equipment / and listed the amount / in the judgment.','pecuniary.s1 指与钱有关的，尤指罚款、损失或收益。','赔偿以具体金额支付。','word-formation'),M('The contract said the worker faced a pecuniary penalty, but the only consequence was a written apology with no financial cost.','The contract said the worker faced a pecuniary penalty of $500.','没有金钱成本的道歉不是金钱上的罚款。','meaning'),[Q(1,'What kind of compensation did the court order?','Money for the damaged equipment.','A public apology with no payment.','A peck of fruit.','pecuniary.s1 concerns money.'),Q(1,'Which issue is pecuniary?','The amount of a fine.','The color of a wall.','The tone of a joke.','A fine is a financial matter.'),Q(1,'What does pecuniary mean?','Connected with money.','Connected with bird behavior.','Peaceful and quiet.','The adjective refers to financial matters.'),Q(1,'Which Latin noun is the historical source of pecuniary?','pecunia','pax','pavimentum','Latin pecunia means money.','word-formation')]);
P('pedagogic','From Greek paidagōgikos, from paidagōgos “teacher/child guide”; pedagogic means concerning the methods and practice of teaching.',C('pedagogic.s1','教育','The review praised the course’s pedagogic approach because learners practiced each skill before moving to the next one.','评审称赞课程的教学方法，因为学习者先练习每项技能，再进入下一项。','The review praised the course’s pedagogic approach / because learners practiced each skill / before moving / to the next one.','pedagogic.s1 指关于教学方法与实践的。','课程安排体现了具体教学实践。','word-formation'),M('The review called the course pedagogic even though it had no teaching, instruction, or learning activity.','The review called the course pedagogic because it organized instruction and practice for learners.','没有教学或学习活动就不属于教学实践。','meaning'),[Q(1,'What did the review praise?','The course’s teaching approach.','Its payroll list.','Its pavement surface.','pedagogic.s1 concerns teaching methods and practice.'),Q(1,'Which issue is pedagogic?','How a teacher sequences practice for beginners.','How a court calculates a fine.','How a bird grows its tail feathers.','The first is about teaching practice.'),Q(1,'What does pedagogic mean?','Concerning teaching methods and practice.','A person who buys from a shop.','A large amount of money.','The adjective relates to teaching.'),Q(1,'What Greek idea is part of the history of pedagogic?','A guide or teacher of children.','A measure of land.','A shell that forms a pearl.','Paidagōgos referred to a child’s guide or teacher.','word-formation')]);
P('pedagogical','From pedagogy + -ical; it means relating to education theory or designed to help students learn.',C('pedagogical.s1','教育','The instructor added a pedagogical diagram that showed each step of the water cycle for younger students.','教师加入了一张教学示意图，为低年级学生展示水循环的每一步。','The instructor added a pedagogical diagram / that showed each step / of the water cycle / for younger students.','pedagogical.s1 指教育学的，或为帮助学生学习而设计的。','图示专门帮助学生理解过程。','word-formation'),M('The instructor called a deliberately confusing diagram pedagogical even though it was designed to prevent students from understanding the topic.','The instructor called the clearly labeled learning diagram pedagogical because it helped students understand the topic.','故意阻碍学习的图示不符合 pedagogical 的教学目的。','meaning'),[Q(1,'What did the pedagogical diagram show?','Each step of the water cycle.','The teacher’s paycheck.','A peasant family’s field.','pedagogical.s1 is designed to support learning.'),Q(1,'Which resource is pedagogical?','A labeled model that helps students understand a process.','A puzzle with no educational aim or explanation.','A decorative pattern on a wall.','The model is designed to help students learn.'),Q(1,'What does pedagogical mean?','Related to education or intended to teach.','Financially payable.','Timid and fearful.','The adjective concerns teaching and learning.'),Q(1,'Which noun is pedagogical related to?','pedagogy','peacock','pavilion','Pedagogical derives from pedagogy.','word-formation')]);
P('pedagogy','From Greek paidagōgia, from paidagōgos “child’s guide or teacher”; it means the art, science, or style of teaching.',C('pedagogy.s1','教育','The school revised its pedagogy so students would explain their reasoning instead of memorizing answers alone.','学校调整了教学方法，让学生解释推理过程，而不是只背答案。','The school revised its pedagogy / so students would explain their reasoning / instead of memorizing / answers alone.','pedagogy.s1 指教学的技艺、学问或风格。','课程方法从单纯记忆转向解释推理。','word-formation'),M('The school called its pedagogy effective even though teachers gave no instruction and students had no learning activities.','The school described its teaching methods and learning activities as its pedagogy.','没有教学方法或学习活动时，不能称为一种 pedagogy。','meaning'),[Q(1,'What change did the school make to its pedagogy?','It asked students to explain their reasoning.','It removed all instruction and learning.','It required only memorization with no thought.','pedagogy.s1 concerns the style and practice of teaching.'),Q(1,'Which issue belongs to pedagogy?','How teachers help learners understand a topic.','How a court awards a financial penalty.','How a pear grows underground.','The first concerns teaching methods.'),Q(1,'What does pedagogy mean?','The art, science, or style of teaching.','A person who pays for a service.','A small stone worn smooth by water.','The noun names teaching theory and practice.'),Q(1,'Which Greek source term referred to a child’s guide?','paidagōgos','pax','paucus','Paidagōgos means a child’s guide or teacher.','word-formation')]);
P('pedal','From Latin pedalis “of the foot,” from pes, ped- “foot”; a pedal is a foot-operated lever, and to pedal is to push such pedals.',[C('pedal.s1','机械','She pressed the brake pedal gently before the bicycle reached the steep part of the hill.','在自行车到达陡坡前，她轻轻踩下刹车踏板。','She pressed the brake pedal gently / before the bicycle reached / the steep part / of the hill.','pedal.s1 指用脚踩的扁平杆或杠杆。','刹车踏板由脚来控制。'),C('pedal.s2','交通','They pedaled along the riverside path at an easy pace and stopped to watch the boats.','他们以轻松的速度沿河边骑行，停下来观看船只。','They pedaled along the riverside path / at an easy pace / and stopped / to watch the boats.','pedal.s2 作动词，指踩踏板驱动车辆。','骑行时反复踩动自行车踏板。')],M('She used the brake pedal by pulling it with her hand while her foot never touched it.','She pressed the brake pedal with her foot to slow the bicycle.','pedal 是脚踩的控制杆，不是手拉的把手。','meaning'),[Q(1,'What did she press before the steep hill?','The foot-operated brake lever.','The bicycle’s bell.','A pavement stone.','pedal.s1 is a flat lever pressed with the foot.'),Q(2,'What did they do along the riverside path?','They pushed the bicycle pedals to ride.','They carried the bicycle without moving its pedals.','They walked beside the road.','pedal.s2 means push the pedals of a bicycle.'),Q(1,'Which is a pedal?','The foot lever that controls a vehicle or machine.','A hand-held map.','A wheel’s tire only.','The lever is operated by the foot.'),Q(2,'Which sentence uses pedal as a verb?','She pedaled uphill to reach the bridge.','She replaced the broken pedal.','The pedal was made of metal.','The first describes the action of cycling.','grammar')]);
P('peddle','Of uncertain origin, recorded in English for selling goods from place to place; figuratively it means try to get people to accept ideas or often dishonest stories.',[C('peddle.s1','商业','The vendor peddled handmade brushes from a cart, stopping at each farm along the road.','小贩推着车沿路在各个农场停下，兜售手工刷子。','The vendor peddled handmade brushes / from a cart / stopping at each farm / along the road.','peddle.s1 指走街串巷地卖商品。','商贩从一处走到另一处卖货。'),C('peddle.s2','社会','The website peddled a false cure online, claiming it worked despite having no reliable evidence.','该网站在网上散布一种虚假的疗法，声称有效却没有可靠证据。','The website peddled a false cure / online / claiming it worked / despite having no reliable evidence.','peddle.s2 指试图让人接受某种想法或说法，常指不诚实的信息。','网站推销未经证实的疗法。')],M('The vendor peddled goods by keeping them at home and refusing to offer them to any customer.','The vendor peddled goods by traveling from farm to farm to sell them.','把商品留在家中不销售，不符合沿街兜售。','meaning'),[Q(1,'What did the vendor peddle from the cart?','Handmade brushes.','A false online cure.','A set of medical textbooks.','peddle.s1 means sell goods from place to place.'),Q(2,'What did the website peddle?','An unsupported false cure.','Handmade brushes at farms.','A verified medical treatment.','peddle.s2 can mean spread or promote a dishonest claim.'),Q(1,'Which action is peddling goods?','Traveling between villages to sell household items.','Keeping items at home and refusing sales.','Buying a product for personal use.','The first seller goes from place to place.'),Q(2,'Which sentence uses peddle for an idea?','The speaker peddled a rumor without checking whether it was true.','The farmer peddled baskets at the market.','The customer paid for a basket.','The first spreads a possibly dishonest story.','distinction')]);
P('peddler','From peddle + -er; it names someone who travels from place to place selling small goods.',C('peddler.s1','商业','A peddler walked through the mountain village selling needles, thread, and small kitchen tools.','一名流动小贩走过山村，出售针、线和小厨房工具。','A peddler walked through the mountain village / selling needles, thread, / and small kitchen tools.','peddler.s1 指四处走动、出售小商品的人。','小贩带着商品逐处销售。','word-formation'),M('The shopkeeper called a customer who bought one item a peddler, although the customer traveled nowhere to sell goods.','The shopkeeper called the traveling seller of small goods a peddler.','购买商品的顾客不是四处销售商品的小贩。','meaning'),[Q(1,'What did the peddler sell in the village?','Needles, thread, and small tools.','Only large farming machines.','A list of employees.','peddler.s1 sells small goods while traveling.'),Q(1,'Who is a peddler?','A traveling seller of small goods.','A customer who buys one product.','A doctor who treats children.','The first matches the source meaning.'),Q(1,'Where might a peddler sell goods?','From village to village or door to door.','Only from a fixed hospital bed.','Only inside a private home where no sales occur.','A peddler travels to find customers.'),Q(1,'How is peddler formed?','peddle + -er','pedal + -ing','pedestal + -al','The suffix -er names the person who peddles goods.','word-formation')]);
P('pedestal','From Italian piedistallo, via French piédestal, from piede “foot” + a base/stand element; a pedestal supports a statue or, figuratively, someone held in high esteem.',[C('pedestal.s1','艺术','The sculptor secured the bronze figure to a stone pedestal in the center of the gallery.','雕塑家把青铜人物像固定在展厅中央的石底座上。','The sculptor secured the bronze figure / to a stone pedestal / in the center / of the gallery.','pedestal.s1 指雕像或柱子所立的支撑底座。','底座承托雕像。'),C('pedestal.s2','通用','The biography did not pedestal the scientist; it described both her discoveries and the mistakes that shaped her work.','这本传记没有把科学家捧上神坛，而是同时写了她的发现和塑造其工作的错误。','The biography did not pedestal the scientist / it described both her discoveries / and the mistakes / that shaped her work.','pedestal.s2 作动词，指把某人或某物置于高位、过分敬仰。','传记没有把她描写成毫无缺点。')],M('The statue rested directly on the floor with no support, but the guide said it stood on a pedestal.','The statue stood on a stone support that raised it above the gallery floor.','没有底座支撑的雕像不符合 pedestal 的字面义。','meaning'),[Q(1,'What supported the bronze figure?','A stone base in the gallery.','A paper invoice.','A moving bicycle pedal.','pedestal.s1 is the support under a statue.'),Q(2,'What did the biography avoid doing?','Putting the scientist on an unquestioned high pedestal.','Describing her discoveries.','Mentioning any work she completed.','pedestal.s2 means place someone in an idealized position.'),Q(1,'Which object is a pedestal?','A raised base beneath a statue.','A flat foot lever on a bicycle.','A small traveling shop.','The base supports and raises the statue.'),Q(2,'Which sentence uses pedestal figuratively?','The fans placed the singer on a pedestal and ignored every flaw.','The statue rested on a marble pedestal.','The sculptor polished the base.','The first describes excessive admiration.','distinction')]);
P('pedestrian','From Latin pedester “on foot,” from pes “foot”; pedestrian can mean a person walking, something intended for walkers, or figuratively something dull and unimaginative.',[C('pedestrian.s1','交通','A pedestrian waited at the marked crossing until the traffic signal turned green.','一名行人在标线人行横道前等候，直到交通灯变绿。','A pedestrian waited / at the marked crossing / until the traffic signal / turned green.','pedestrian.s1 指正在步行的人，尤指城里未乘车的人。','行人等待过马路。'),C('pedestrian.s2','交通','The city added a pedestrian bridge so people could cross the busy road without entering traffic.','市政府增建了一座人行天桥，让行人无需进入车流就能穿过繁忙道路。','The city added a pedestrian bridge / so people could cross / the busy road / without entering traffic.','pedestrian.s2 作形容词，指与步行有关或供行人使用的。','桥供步行者过街。'),C('pedestrian.s3','评论','The reviewer found the novel’s ending pedestrian because it repeated a familiar twist without adding a fresh idea.','评论家觉得小说结尾平淡乏味，因为它重复了熟悉的反转，没有新意。','The reviewer found the novel’s ending pedestrian / because it repeated a familiar twist / without adding / a fresh idea.','pedestrian.s3 作形容词，指普通乏味、缺乏想象力的。','重复套路让结尾显得平庸。')],M('The city called a walkway pedestrian even though cars alone used it and people were forbidden to enter.','The city called the foot-only bridge a pedestrian bridge.','只供汽车通行的桥不是供行人步行的。','meaning'),[Q(1,'Who waited at the marked crossing?','A person traveling on foot.','A driver inside a bus.','A cyclist carrying a package.','pedestrian.s1 is a person walking.'),Q(2,'What is a pedestrian bridge for?','People to cross on foot.','Cars to park overnight.','A train to load cargo.','pedestrian.s2 describes something intended for walkers.'),Q(3,'Why did the reviewer call the ending pedestrian?','It repeated a familiar twist without fresh ideas.','It was set on a busy sidewalk.','It featured an unusual new plot.','pedestrian.s3 means dull and unimaginative.'),Q(1,'Which sentence uses pedestrian as a noun?','A pedestrian crossed at the light.','The pedestrian lane was closed.','The ending felt pedestrian.','The first names a person on foot.','grammar')]);
P('pediatrician','From pediatrics + -ian; pediatrics combines Greek pais/paid “child” + iatros “physician”; a pediatrician specializes in infants, children, and adolescents.',C('pediatrician.s1','医学','The pediatrician checked the toddler’s growth and discussed routine vaccinations with the parents.','儿科医生检查了幼儿的生长情况，并与父母讨论常规疫苗接种。','The pediatrician checked the toddler’s growth / and discussed routine vaccinations / with the parents.','pediatrician.s1 指专门照护婴幼儿、儿童和青少年的医生。','生长检查与儿童疫苗属于儿科医疗。','word-formation'),M('The pediatrician treated only adult heart patients and had no training in caring for children.','The pediatrician examined the child and advised the parents about age-appropriate care.','只治疗成人且没有儿童保健资质的人不符合儿科医生定义。','meaning'),[Q(1,'What did the pediatrician check?','The toddler’s growth.','A bridge’s foundation.','The company payroll.','pediatrician.s1 specializes in children’s care.'),Q(1,'Who should see a pediatrician?','A child needing a routine health check.','A statue needing a new pedestal.','A company seeking a new patron.','A pediatrician cares for infants and children.'),Q(1,'What does a pediatrician specialize in?','Medical care for infants, children, and adolescents.','Only adult farm injuries.','Teaching methods.','The word names a child-health specialist.'),Q(1,'Which Greek element means “physician”?','iatros','paid','pater','Iatros means physician.','word-formation')]);
P('pediatrics','From Greek pais/paid “child” + iatros “physician,” with the field suffix; pediatrics is the medical care and study of children’s diseases.',C('pediatrics.s1','医学','The hospital expanded its pediatrics clinic to provide developmental checks and treatment for childhood illnesses.','医院扩建了儿科门诊，为儿童疾病提供治疗并进行发育检查。','The hospital expanded its pediatrics clinic / to provide developmental checks / and treatment / for childhood illnesses.','pediatrics.s1 指儿童疾病的医疗与研究。','门诊为儿童提供检查和治疗。','word-formation'),M('The hospital labeled its adult cardiology clinic pediatrics even though it treated only older adults.','The hospital labeled its children’s health and disease clinic pediatrics.','只治疗成年人的心脏科不属于儿科。','meaning'),[Q(1,'What does the pediatrics clinic provide?','Checks and treatment for children.','Legal advice about property ownership.','Veterinary care for peafowl only.','pediatrics.s1 is medical care and study of children’s diseases.'),Q(1,'Which field is pediatrics?','The medical study and care of children.','The study of ancient environments.','The method of paving roads.','Pediatrics concerns children’s health.'),Q(1,'What kind of patient is central to pediatrics?','An infant or child.','A company’s payroll clerk.','A statue in a gallery.','The field focuses on infants and children.'),Q(1,'Which roots contribute to pediatrics?','Greek child + physician.','Latin foot + stone.','Old French country + friend.','The word combines child and physician roots.','word-formation')]);
P('pedigree','From Anglo-Norman pied de grue “crane’s foot,” referring to the branching shape of a family chart; pedigree means ancestry or a record of an idea/method’s origins.',[C('pedigree.s1','通用','The breeder checked the dog’s pedigree to confirm its ancestors and screen for inherited health risks.','饲养员查看狗的家谱，以确认其祖先并筛查遗传健康风险。','The breeder checked the dog’s pedigree / to confirm its ancestors / and screen for / inherited health risks.','pedigree.s1 指人、动物或植物的祖先谱系，常有书面记录。','谱系记录了祖先来源。'),C('pedigree.s2','通用','The software’s research pedigree showed how the current method developed from earlier studies.','该软件的研究沿革展示了当前方法如何从早期研究发展而来。','The software’s research pedigree showed / how the current method developed / from earlier studies.','pedigree.s2 指能说明某种想法或方法来源的长期沿革。','研究记录说明方法的历史来源。')],M('The breeder claimed the dog had a complete pedigree but could name no ancestors and had no records.','The breeder supported the dog’s pedigree with records identifying several generations of ancestors.','没有祖先信息或记录就不能称为完整谱系。','meaning'),[Q(1,'Why did the breeder check the dog’s pedigree?','To confirm ancestors and inherited health risks.','To measure the dog’s walking speed.','To check the breeder’s paycheck.','pedigree.s1 is a recorded line of ancestry.'),Q(2,'What did the software’s research pedigree show?','How the method developed from earlier studies.','The dog’s family members.','A pedestrian bridge design.','pedigree.s2 is the history or origin record of a method.'),Q(1,'Which document might contain a pedigree?','A record listing several generations of a horse’s ancestors.','A one-day weather report.','A café menu with no family information.','A pedigree records ancestry.'),Q(1,'Why is the family chart called a pedigree?','Its branching lines resemble a crane’s foot.','It lists every payment due.','It is shaped like a bicycle pedal.','The phrase pied de grue means “crane’s foot.”','word-formation')]);
P('pee','An informal euphemism related to the letter-name P and the verb piss; it means urine as a noun or urinate as a verb.',[C('pee.s1','健康','The urine test required a small sample of pee in the sealed cup provided by the clinic.','尿检要求把少量尿液放进诊所提供的密封杯中。','The urine test required / a small sample of pee / in the sealed cup / provided by the clinic.','pee.s1 是口语说法，指尿液。','样本是要检测的尿液。'),C('pee.s2','健康','The nurse asked whether the child needed to pee before the long bus ride began.','长途巴士出发前，护士问孩子是否需要小便。','The nurse asked / whether the child needed to pee / before the long bus ride / began.','pee.s2 作动词，指排尿；语气非正式。','询问的是孩子是否需要去洗手间。','register')],M('The nurse said the child needed to pee but meant that the child needed to drink a glass of water and not urinate.','The nurse said the child needed to pee before boarding the bus.','pee 的动词义是排尿，不是喝水。','meaning'),[Q(1,'What was placed in the clinic’s sealed cup?','A small urine sample.','A medical paycheck.','A pebble.','pee.s1 means urine.'),Q(2,'What did the nurse ask the child?','Whether the child needed to urinate.','Whether the child needed to climb a peak.','Whether the child had a pedigree.','pee.s2 is the verb meaning urinate.'),Q(1,'Which sentence uses pee as a noun?','The sample of pee was sent to the lab.','The child needed to pee.','The nurse asked a question.','The first uses pee to name urine.'),Q(2,'What is the tone of pee?','Informal.','Highly formal medical Latin.','A legal term for embezzlement.','Pee is an informal euphemism.','register')]);
P('peek','A variant related to peep, with uncertain early history; it means look quickly and secretly at something.',C('peek.s1','通用','Nina peeked through the half-open door to see whether the guests had arrived.','妮娜从半开的门缝里偷看，想知道客人是否到了。','Nina peeked through the half-open door / to see / whether the guests had arrived.','peek.s1 指快速而秘密地看某物。','她没有开门进入，只从门缝快速看了一眼。'),M('Nina peeked at the guests by standing in front of them and staring openly for several minutes.','Nina peeked through the doorway for a brief, secret look at the guests.','公开长时间注视不是快速而秘密地偷看。','distinction'),[Q(1,'How did Nina check whether the guests had arrived?','She looked through the half-open door briefly.','She entered the room and announced herself.','She watched them openly for several minutes.','peek.s1 means look quickly and secretly.'),Q(1,'Which action is peeking?','Glancing through a curtain gap without being noticed.','Standing in full view and waving.','Closing the curtain and leaving.','The first is a quick secret look.'),Q(1,'What does peek mean?','Take a quick, secret look.','Walk quietly across a hall.','Throw something repeatedly.','Peek is a brief concealed look.'),Q(1,'Which phrase commonly follows peek?','peek through a door','peek a paycheck','peek a pail','Peek through a gap describes looking secretly.','collocation')]);
P('peel','From Middle English pelen, related to removing an outer skin; peel can mean remove a fruit/vegetable skin, come off in thin layers, or the skin removed.',[C('peel.s1','饮食','She peeled the orange over a bowl so the juice would not drip onto the table.','她在碗上方剥橙子，以免汁水滴到桌上。','She peeled the orange / over a bowl / so the juice / would not drip onto the table.','peel.s1 作动词，指去掉水果或蔬菜外皮。','她把橙子的外皮剥下来。'),C('peel.s2','通用','The paint began to peel from the damp window frame in thin curls.','潮湿窗框上的油漆开始一片片卷起脱落。','The paint began to peel / from the damp window frame / in thin curls.','peel.s2 作动词，指表面脱落或失去外层。','油漆层从窗框剥落。'),C('peel.s3','饮食','Put the potato peel in the compost bucket rather than throwing it into the sink.','把土豆皮放进堆肥桶，不要扔进水槽。','Put the potato peel / in the compost bucket / rather than throwing it / into the sink.','peel.s3 作名词，指削下来的果皮或菜皮。','土豆皮是去掉的外层。')],M('The cook peeled the orange by leaving its entire skin on and cutting only the fruit into slices.','The cook peeled the orange by removing its outer skin before slicing it.','保留外皮不算去皮。','meaning'),[Q(1,'What did she do to the orange?','Removed its outer skin.','Painted it orange.','Placed it in a compost bucket.','peel.s1 is the verb for removing fruit skin.'),Q(2,'What happened to the paint on the window frame?','It came off in thin curls.','It was peeled from an orange.','It became a vegetable peel.','peel.s2 means come off in layers.'),Q(3,'Where should the potato peel go?','In the compost bucket.','On the painted window frame.','Back onto the potato.','peel.s3 is the removed skin.'),Q(1,'Which action means peel an apple?','Take off its outer skin.','Paint it a new color.','Put it in a pail.','Peeling removes the fruit’s skin.','meaning')]);
P('peep','Imitative in origin, echoing a small bird’s high call; peep can mean look secretly through a small opening, a quick secret look, or make a short weak high sound.',[C('peep.s1','通用','The child peeped through the keyhole to check whether the surprise party guests were ready.','孩子从钥匙孔里偷看，确认惊喜派对的客人是否准备好了。','The child peeped through the keyhole / to check / whether the surprise party guests / were ready.','peep.s1 指快速或偷偷地看，常从小孔向外看。','钥匙孔提供了隐蔽的小视野。'),C('peep.s2','通用','She took a quick peep at the stage curtain before the doors opened to the audience.','观众入场前，她快速窥看了一眼舞台帷幕后面。','She took a quick peep / at the stage curtain / before the doors opened / to the audience.','peep.s2 作名词，指迅速或偷偷的一瞥。','quick peep 是短暂的一看。'),C('peep.s3','动物','The hungry nestling peeped weakly until its parent returned with food.','饥饿的雏鸟微弱地吱吱叫，直到亲鸟带着食物回来。','The hungry nestling peeped weakly / until its parent returned / with food.','peep.s3 指小鸟、老鼠等发出短而弱的高音。','雏鸟发出细小叫声。')],M('The nestling peeped by making a loud, low roar that shook the windows.','The nestling peeped with a short, weak, high call.','微弱高音与响亮低吼相反。','meaning'),[Q(1,'What did the child do at the keyhole?','Looked secretly through the small opening.','Made a bird call.','Opened the door for the guests.','peep.s1 is a quick secret look through a small space.'),Q(2,'What did she take before the doors opened?','A brief look at the stage curtain.','A loud high call.','A full tour of the theater.','peep.s2 is a quick or secret look.'),Q(3,'What sound did the nestling make?','A short, weak, high call.','A loud low roar.','A church bell’s long ring.','peep.s3 describes a small high sound.'),Q(1,'Which action is peeping through a hole?','Looking quickly through a keyhole.','Calling loudly from a stage.','Removing the peel of a pear.','The first is a secret look through an opening.','distinction')]);
P('peepshow','A compound of peep + show; it is a display viewed through a small opening, historically a box of pictures and later sometimes an adult sexual display.',C('peepshow.s1','文化','At the fair, a historical peepshow box let visitors view illustrated scenes through a small round hole.','集市上的历史画片箱让游客通过一个小圆孔观看插图场景。','At the fair / a historical peepshow box / let visitors view illustrated scenes / through a small round hole.','peepshow.s1 指从小孔观看的展示，历史上常是装图片的画片箱，后来也可指色情展示。','例句明确是传统图片箱的历史用法。','word-formation'),M('The fair called an open-air mural with no viewing hole a peepshow box.','The fair called the picture display viewed through a small hole a peepshow.','没有小孔观看结构的壁画不符合画片箱式 peepshow。','meaning'),[Q(1,'How did visitors view the fair’s peepshow?','Through a small round hole.','By reading a printed menu.','By watching a parade from a rooftop.','peepshow.s1 is viewed through a small opening.'),Q(1,'What was a historical peepshow box?','A box of pictures seen through a small opening.','A large open mural on a wall.','A public lecture about teaching.','The historical display was viewed through a hole.'),Q(1,'What does peepshow combine?','peep + show','pea + show','pearl + show','The compound names a show one peeps through.'),Q(1,'Which feature is central to the traditional peepshow?','A small opening for viewing images inside.','A stage visible from every direction.','A loud speaker system.','The viewer looks through an opening.','meaning')]);
P('peer','From Latin par “equal,” via Old French per; peer can mean someone of equal age/rank, a British titled noble, or the verb to look carefully with difficulty.',[C('peer.s1','社会','Each student reviewed the draft with a peer from the same class before submitting it.','每名学生在提交前都与同班同学互相审阅草稿。','Each student reviewed the draft / with a peer / from the same class / before submitting it.','peer.s1 指年龄、地位或能力相同的人。','同班同学是同辈。'),C('peer.s2','政治','The British peer attended the House of Lords wearing the robes associated with his hereditary title.','这位英国贵族身穿与其世袭头衔相配的礼袍，出席上议院会议。','The British peer attended the House of Lords / wearing the robes / associated with his hereditary title.','peer.s2 指拥有公爵、伯爵等头衔的英国贵族。','头衔与上议院语境体现贵族义。'),C('peer.s3','通用','She peered through the fogged window, trying to read the street sign in the dim light.','她透过起雾的窗户费力凝视，试图在昏暗光线下读出路牌。','She peered through the fogged window / trying to read the street sign / in the dim light.','peer.s3 作动词，指因光线差或视力弱而仔细、吃力地看。','雾气和暗光让她必须仔细看。')],M('The student reviewed the draft with a peer who was a titled British duke, although they had never met as classmates or equals.','The student reviewed the draft with a classmate of similar age and standing, a peer.','普通同辈语境中，peer 指同龄或同等地位者，不要求贵族头衔。','distinction'),[Q(1,'Who reviewed each student’s draft?','A classmate of similar age and standing.','A titled British noble.','A person staring through a fogged window.','peer.s1 means someone of equal age or status.'),Q(2,'Why was the visitor called a British peer?','He held a hereditary noble title.','He was a classmate reviewing a draft.','He was trying to read a sign in fog.','peer.s2 names a member of the British nobility.'),Q(3,'What was she doing at the window?','Looking carefully through fog in dim light.','Reviewing a classmate’s draft.','Attending the House of Lords.','peer.s3 means look with effort or difficulty.'),Q(1,'Which person is a peer in the everyday sense?','A colleague at the same professional level.','A manager with authority over everyone.','A visitor who never joins the group.','A peer is someone of similar rank or ability.','distinction')]);
P('peerless','English peerless is recorded from about 1300, formed from peer + -less “without an equal”; peer traces through Anglo-French and Old French to Latin par “equal.”',C('peerless.s1','通用','The young pianist gave a peerless performance, and the judges could name no other contestant who matched its precision and warmth.','这位年轻钢琴家带来了一场无与伦比的演出，评委们找不到其他选手能与其精准和温暖相媲美。','The young pianist gave / a peerless performance / and the judges could name no other contestant / who matched its precision and warmth.','peerless.s1 指同类中无可匹敌的、无双的。','评委找不到可相比的选手，说明演出无与伦比。','word-formation'),M('The guide called the performance peerless because several other contestants clearly performed better.','The guide called the performance peerless because no other contestant matched its quality.','peerless 表示没有同类能相比；若多人明显胜过它，就不能称为 peerless。','meaning'),[Q(1,'Why did the judges call the pianist’s performance peerless?','No other contestant matched its quality.','It was the shortest performance.','The pianist performed with a large group.','Peerless means unequaled or unmatched.','meaning'),Q(1,'Which achievement is peerless?','A record no other competitor has equaled.','A result matched by every competitor.','A performance that was never judged.','Peerless describes something with no equal.','meaning'),Q(1,'What does the ending -less contribute to peerless?','The idea of lacking an equal.','The idea of comparing two peers.','The idea of performing again.','Peer + -less means without a peer or equal.','word-formation'),Q(1,'Which paraphrase best preserves “a peerless performance”?','An unmatched performance.','A performance by a classmate.','A performance with several equal winners.','Peerless means outstanding with no equal.','meaning')]);
P('peg','The noun peg is recorded from the mid-15th century, from Middle Dutch pegge or a similar Low German word; its deeper origin is uncertain. The verb comes from the noun, and “fix a market price” is recorded by 1882.',[C('peg.s1','日常','Mara hung the damp jacket on a wooden peg beside the door so it could dry overnight.','玛拉把湿夹克挂在门边的木钉上，让它晾一夜。','Mara hung the damp jacket / on a wooden peg / beside the door / so it could dry overnight.','peg.s1 作名词，指用于固定或悬挂物品的短钉。','木钉用来挂夹克。'),C('peg.s2','日常','We pegged the picnic blanket to the grass at each corner before the wind picked up.','起风前，我们用地钉把野餐毯的四角固定在草地上。','We pegged the picnic blanket / to the grass at each corner / before the wind picked up.','peg.s2 作动词，指用钉或夹子固定。','四角都被地钉固定。'),C('peg.s3','金融','The country pegged its currency to the euro, keeping the exchange rate within a fixed range.','该国将本国货币与欧元挂钩，把汇率维持在固定区间内。','The country pegged its currency to the euro / keeping the exchange rate / within a fixed range.','peg.s3 指把价格、汇率或价值固定在某个水平或与另一标准挂钩。','汇率受固定区间约束。')],M('The country pegged its currency to the euro by letting its exchange rate float freely without a target or limit.','The country pegged its currency to the euro by keeping its exchange rate within a fixed range.','“固定挂钩”与“完全自由浮动、没有目标”相互矛盾。','meaning'),[Q(1,'What held Mara’s jacket beside the door?','A short wooden pin used as a hanger.','A currency exchange rate.','A blanket corner tied to grass.','Peg.s1 is a short pin used to fasten or hang something.'),Q(2,'How did the group stop the blanket from blowing away?','They fastened its corners to the grass with pegs.','They fixed a currency rate to the euro.','They hung it from the door.','To peg something can mean fasten it with pegs.'),Q(3,'What did the country do to its currency?','It linked its exchange rate to the euro within a fixed range.','It let the rate float with no target.','It attached coins to a wooden pin.','Peg.s3 means fix or link a price or rate at a set level.'),Q(1,'Which sentence uses peg as a noun?','A coat hangs from a peg by the entrance.','They peg the tent corners before the storm.','The bank pegs the currency to the euro.','In this sentence peg names the short pin.','distinction')]);
P('pejorative','Pejorative entered English from French péjoratif in 1888, from Late Latin peiorat- “make worse,” based on Latin peior “worse”; its noun use for a disparaging word is recorded from 1882.',[C('pejorative.s1','语言','The editor removed the pejorative adjective because it described the community with contempt rather than evidence.','编辑删掉了那个贬损性形容词，因为它带着蔑视而非依据来描述该群体。','The editor removed / the pejorative adjective / because it described the community / with contempt rather than evidence.','pejorative.s1 作形容词，指带有贬低或轻蔑意味的。','形容词表达蔑视，属于贬损用语。'),C('pejorative.s2','语言','The term “cripple” is now widely recognized as a pejorative and should not be used to refer to a person with a disability.','如今，“cripple”普遍被视为贬义词，不应用来称呼残障人士。','The term “cripple” / is now widely recognized / as a pejorative / and should not be used to refer to a person with a disability.','pejorative.s2 作名词，指带有贬损意味的词。','例句把该词直接作为一类词语来称呼。')],M('The reviewer called the insult pejorative because it respectfully praised the person without any contempt.','The reviewer called the insult pejorative because it expressed contempt for the person.','表示尊重赞扬且毫无轻蔑的用语不是 pejorative。','meaning'),[Q(1,'Why did the editor remove the adjective?','It described the community with contempt.','It supplied a neutral statistic.','It praised the group respectfully.','A pejorative adjective carries disparagement or scorn.'),Q(2,'In the second example, what is a pejorative?','A word with a disparaging meaning.','A neutral number in a report.','A respectful title for a person.','The noun pejorative names a disparaging word.'),Q(2,'Which word is functioning as a pejorative noun in “That label is a pejorative”?','pejorative','disparaging','editor','As a noun, a pejorative is a disparaging word or label.','distinction'),Q(1,'What does the history from Latin peior, “worse,” help explain?','Why pejorative describes language that puts something in a bad or contemptuous light.','Why it always means a neutral technical term.','Why it refers only to a person’s job title.','Its history is linked to making worse and to disparaging meaning.','word-formation')]);
P('pellet','Pellet is recorded from the mid-14th century through Old French pelote “small ball,” ultimately from Vulgar Latin *pilotta, a diminutive of Latin pila “ball”; the verb “form into little balls” comes from the noun.',[C('pellet.s1','材料','The clinic gave the rabbit a tiny medicine pellet hidden inside a piece of banana.','诊所把一粒藏在香蕉片里的小药丸喂给了兔子。','The clinic gave the rabbit / a tiny medicine pellet / hidden inside a piece of banana.','pellet.s1 指药物、食物等制成的小球或颗粒。','小药丸是小球状剂量。'),C('pellet.s2','制造','The feed machine pellets the powdered grain into small, firm cylinders for storage.','饲料机把谷物粉压制成坚实的小颗粒，便于储存。','The feed machine pellets the powdered grain / into small firm cylinders / for storage.','pellet.s2 作动词，指把材料制成小球或颗粒。','机器把粉末压成颗粒。','word-formation')],M('The machine pelleted the feed by dissolving the powder into a clear liquid with no solid pieces.','The machine pelleted the feed by pressing the powder into small solid pieces.','pellet 作动词是制成小颗粒，不是溶解成没有固体的液体。','meaning'),[Q(1,'What did the rabbit receive?','A tiny ball-shaped dose of medicine.','A wooden peg for its cage.','A large bottle of liquid medicine.','A pellet is a small ball or compact piece of material.'),Q(2,'What does the feed machine do when it pellets grain?','It presses the powder into small solid pieces.','It dissolves all the grain into liquid.','It throws the grain at a target.','The verb means form material into small pellets.'),Q(1,'Which item is most clearly a pellet?','A small compressed ball of animal feed.','A long sheet of paper.','A full-sized loaf of bread.','A pellet is a small compact ball or piece.'),Q(1,'Which process would make pellets from powder?','Pressing the powder into small round pieces.','Spreading the powder into a thin liquid.','Hanging the powder on a peg.','To pellet material is to form it into small balls or pieces.','word-formation')]);
P('pelt','The noun pelt, recorded in the early 15th century for a fur-bearing animal’s skin, has uncertain origin; one proposal links it to Anglo-Latin pelet and Old French pelete “fine skin.” The verb pelt “strike repeatedly” is a separate word of unknown origin; “rain pelted down” is recorded by 1862.',[C('pelt.s1','自然','The furrier inspected the fox pelt for tears before preparing it for preservation.','毛皮商在处理保存前检查了这张狐狸皮是否有破损。','The furrier inspected / the fox pelt / for tears / before preparing it for preservation.','pelt.s1 指仍带着毛的动物皮。','狐狸皮仍保留着毛。'),C('pelt.s2','动作','Protesters pelted the armored vehicle with soft fruit, but no one was injured.','抗议者向装甲车反复投掷软水果，但没有人受伤。','Protesters pelted the armored vehicle / with soft fruit / but no one was injured.','pelt.s2 指用物品猛烈而反复地投向某人或某物。','水果被反复投出。'),C('pelt.s3','天气','Rain pelted down on the campsite all night, drumming loudly against the tent roof.','雨整夜倾盆而下，重重敲打着帐篷顶。','Rain pelted down / on the campsite all night / drumming loudly / against the tent roof.','pelt.s3 指雨势很大地落下。','整夜的雨猛烈敲打帐篷。')],M('During the storm, rain pelted down as a barely noticeable mist that left the pavement dry.','During the storm, rain pelted down in heavy drops that soaked the pavement.','pelt down 表示雨猛烈地下；几乎察觉不到的雾且地面干燥与之相反。','meaning'),[Q(1,'What did the furrier inspect?','An animal skin that still had its fur.','A ball of compressed feed.','A wooden pin used to hang a coat.','A pelt is the furred skin of an animal.'),Q(2,'What did the protesters do to the vehicle?','They repeatedly threw soft fruit at it.','They examined its animal hide.','They fixed its exchange rate.','To pelt something is to hit it with repeated throws.'),Q(3,'How did the rain fall on the campsite?','Very heavily throughout the night.','As a dry haze that never touched the tent.','In one brief drop and then stopped.','Rain pelted down means it fell very heavily.'),Q(2,'Which use of pelt is about throwing objects?','The crowd pelted the stage with paper balls.','Rain pelted down on the roof.','The furrier sold a wolf pelt.','The first sentence uses the verb for repeatedly throwing things.','distinction')]);

})();
